class OracleJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.integer, np.int64)):
            return int(obj)
        if isinstance(obj, (np.floating, np.float64)):
            v = float(obj)
            if np.isnan(v) or np.isinf(v):
                return 0.0
            return v
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, (datetime, date)):
            return obj.isoformat()
        return super().default(obj)

    def encode(self, o):
        o = self._sanitize(o)
        return super().encode(o)

    def _sanitize(self, obj):
        if isinstance(obj, dict):
            return {str(k): self._sanitize(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [self._sanitize(v) for v in obj]
        if isinstance(obj, tuple):
            return [self._sanitize(v) for v in obj]
        if isinstance(obj, float):
            if obj != obj or abs(obj) == float('inf'):
                return 0.0
            return obj
        if isinstance(obj, (np.floating, np.float64)):
            v = float(obj)
            if np.isnan(v) or np.isinf(v):
                return 0.0
            return v
        if isinstance(obj, (np.integer, np.int64)):
            return int(obj)
        return obj


def _serialize(obj):
    return json.loads(OracleJSONEncoder().encode(obj))


def _skewness(returns):
    n = len(returns)
    if n < 3:
        return 0.0
    mu = np.mean(returns)
    sigma = np.std(returns, ddof=1)
    if sigma < 1e-10:
        return 0.0
    return float(np.mean(((returns - mu) / sigma) ** 3))


def _kurtosis(returns):
    n = len(returns)
    if n < 4:
        return 0.0
    mu = np.mean(returns)
    sigma = np.std(returns, ddof=1)
    if sigma < 1e-10:
        return 0.0
    return float(np.mean(((returns - mu) / sigma) ** 4) - 3)


