                    options: { responsive: true, plugins: {legend: {display: false}}, scales: {y: {min: -1, max: 1, grid: {color: 'rgba(255,255,255,0.05)'}, ticks: {color: '#888'}}, x: {grid: {display: false}, ticks: {color: '#ccc'}}} }
