@app.get("/api/timeslider")
async def time_slider(
    days: int = Query(default=1825, ge=30, le=7300),
    confidence: str = Query(default="high"),
):
    target_date = date.today() + timedelta(days=days)
    confidence_map = {
        "low": ConfidenceLevel.LOW,
        "medium": ConfidenceLevel.MEDIUM,
        "high": ConfidenceLevel.HIGH,
        "very_high": ConfidenceLevel.VERY_HIGH,
    }
    conf = confidence_map.get(confidence.lower(), ConfidenceLevel.HIGH)

    ts = slider.slide_to(target_date, conf)
    return json.loads(json.dumps(ts.summary, default=_serialize))


@app.post("/api/scenario")
async def scenario_analysis(request: PredictRequest):
    scenarios = {
        "baseline": {},
        "bull_case": {"gdp_growth_rate": 0.04, "inflation_rate": 0.02, "unemployment_rate": 0.03},
        "bear_case": {"gdp_growth_rate": -0.01, "inflation_rate": 0.06, "unemployment_rate": 0.08},
        "stagflation": {"gdp_growth_rate": 0.005, "inflation_rate": 0.08, "unemployment_rate": 0.07},
        "deleveraging": {"gdp_growth_rate": 0.01, "debt_to_gdp": 3.5, "inflation_rate": 0.01},
    }

    try:
        target_date = date.fromisoformat(request.target_date)
    except ValueError:
        raise HTTPException(status_code=422, detail="Invalid date format.")

    if request.economic_state:
        es = request.economic_state
        engine.set_economic_state(
            gdp_growth_rate=es.gdp_growth_rate, debt_to_gdp=es.debt_to_gdp,
            interest_rate=es.interest_rate, inflation_rate=es.inflation_rate,
            unemployment_rate=es.unemployment_rate, stock_valuation=es.stock_valuation,
        )

    results = slider.scenario_analysis(scenarios, target_date)
    output = {}
    for name, ts in results.items():
        output[name] = ts.summary

    return json.loads(json.dumps(output, default=_serialize))


@app.get("/api/cycles")
async def detect_cycles(
    variable: str = Query(default="sp500"),
    method: str = Query(default="all"),
):
    real_data_map = {
        "sp500": "sp500", "nasdaq": "nasdaq", "vix": "vix",
        "gold": "gold", "treasury_10y": "treasury_10y",
    }
    series = None
    data_source = "synthetic"

    if variable in real_data_map:
        try:
            real_arr = data_fetcher.get_close_array(real_data_map[variable], period="2y")
            if real_arr is not None and len(real_arr) > 30:
                series = real_arr
                data_source = "real"
        except Exception:
            pass

    if series is None:
        np.random.seed(42)
        synthetic_map = {
            "gdp": np.cumsum(np.random.normal(0.0002, 0.01, 120)) + 100,
            "inflation": np.cumsum(np.random.normal(0.0001, 0.005, 120)) + 2,
            "unemployment": np.cumsum(np.random.normal(-0.00005, 0.003, 120)) + 5,
            "stock": np.cumsum(np.random.normal(0.0005, 0.015, 120)) + 100,
            "sp500": np.cumsum(np.random.normal(0.0005, 0.015, 120)) + 100,
        }
        series = synthetic_map.get(variable, synthetic_map["sp500"])

    cycles = CycleDetector().detect_cycles(series)
    anomalies = AnomalyDetector().detect_all(series)
    try:
        regime = RegimeDetector().detect_hmm_regimes(series)
        regime_info = {"current_regime": regime.current_regime, "regime_probabilities": regime.regime_probabilities}
    except Exception:
        regime_info = {"current_regime": "unknown", "regime_probabilities": {}}

    return {
        "variable": variable,
        "data_source": data_source,
        "n_data_points": len(series),
        "cycles": [
            {"period": c.dominant_period, "frequency": c.dominant_frequency,
             "strength": c.strength, "phase": c.phase}
            for c in cycles
        ],
        "anomalies": len(anomalies),
        "current_regime": regime_info["current_regime"],
        "regime_probabilities": regime_info["regime_probabilities"],
    }


