@app.get("/api/market-history")
async def market_history(
    symbols: str = Query(default="sp500,nasdaq,vix,gold,oil,treasury_10y", description="Comma-separated symbols"),
    period: str = Query(default="6mo", description="Period: 1mo, 3mo, 6mo, 1y, 2y"),
    interval: str = Query(default="1wk", description="Interval: 1d, 1wk, 1mo"),
):
    try:
        symbol_list = [s.strip() for s in symbols.split(",") if s.strip()]
        result = {}
        for symbol in symbol_list:
            data = data_fetcher.fetch_series(symbol, period=period, interval=interval)
            if data is not None and len(data) > 0:
                dates = [d.strftime("%Y-%m-%d") for d in data.index]
                close_vals = []
                if "Close" in data.columns:
                    close_series = data["Close"]
                    close_vals = [float(v) if not (v != v) else None for v in close_series]
                result[symbol] = {"dates": dates, "close": close_vals}
        return {"symbols": symbol_list, "period": period, "interval": interval, "data": result, "timestamp": datetime.now().isoformat()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/correlation")
async def correlation_matrix(
    symbols: str = Query(default="sp500,nasdaq,gold,oil,treasury_10y,bitcoin", description="Comma-separated symbols"),
    period: str = Query(default="1y", description="Period for correlation calc"),
):
    try:
        symbol_list = [s.strip() for s in symbols.split(",") if s.strip()]
        multi = data_fetcher.fetch_multi(symbol_list, period=period)
        if len(multi) < 2:
            return {"correlation_matrix": {}, "available_symbols": list(multi.keys()), "message": "Insufficient data for correlation"}

        returns_dict = {}
        for name, arr in multi.items():
            if arr is not None and len(arr) > 2:
                rets = np.diff(arr) / arr[:-1]
                returns_dict[name] = rets

        symbol_names = list(returns_dict.keys())
        n = len(symbol_names)
        if n < 2:
            return {"correlation_matrix": {}, "available_symbols": symbol_names, "message": "Need at least 2 symbols"}

        min_len = min(len(returns_dict[s]) for s in symbol_names)
        aligned = np.column_stack([returns_dict[s][:min_len] for s in symbol_names])
        corr = np.corrcoef(aligned, rowvar=False)

        labels = {
            "sp500": "S&P 500", "nasdaq": "NASDAQ", "vix": "VIX", "gold": "Gold",
            "oil": "Oil", "treasury_10y": "10Y Treasury", "bitcoin": "Bitcoin",
            "usd_index": "USD Index", "dji": "DJI", "russell_2000": "Russell 2000",
        }

        matrix = {}
        for i in range(n):
            for j in range(n):
                key = f"{symbol_names[i]}_{symbol_names[j]}"
                matrix[key] = round(float(corr[i][j]), 4)

        return {
            "correlation_matrix": matrix,
            "symbols": symbol_names,
            "labels": {s: labels.get(s, s) for s in symbol_names},
            "n_observations": min_len,
            "period": period,
            "timestamp": datetime.now().isoformat(),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/risk-assessment")
async def risk_assessment():
    try:
        domain_states = domain_fetcher.get_all_domain_states()
        snapshot = data_fetcher.get_economic_snapshot()

        risks = {}
        scores = {}

        sentiment = domain_states.get("sentiment", {})
        fg = sentiment.get("fear_greed_index", 0.5)
        vix_norm = sentiment.get("vix_level", 0.3)
        risks["sentiment"] = {
            "level": "EXTREME_FEAR" if fg < 0.2 else "FEAR" if fg < 0.4 else "NEUTRAL" if fg < 0.6 else "GREED" if fg < 0.8 else "EXTREME_GREED",
            "score": round(1.0 - fg, 3),
            "drivers": {"fear_greed": round(fg, 3), "vix_level": round(vix_norm, 3), "put_call": sentiment.get("put_call_ratio", 0.7), "safe_haven": sentiment.get("safe_haven_demand", 0.4)},
        }
        scores["sentiment"] = 1.0 - fg

        contagion = domain_states.get("contagion", {})
        systemic = contagion.get("financial_systemic_risk", 0.3)
        risks["contagion"] = {
            "level": "CRITICAL" if systemic > 0.7 else "HIGH" if systemic > 0.5 else "MODERATE" if systemic > 0.3 else "LOW",
            "score": round(systemic, 3),
            "drivers": {"systemic_risk": round(systemic, 3), "banking": round(contagion.get("banking_contagion", 0.2), 3), "sovereign": round(contagion.get("sovereign_contagion", 0.25), 3), "currency_stress": round(contagion.get("currency_stress", 0.2), 3)},
        }
        scores["contagion"] = systemic

        geopolitical = domain_states.get("geopolitical", {})
        geo_score = (geopolitical.get("us_china_tension", 0.4) + geopolitical.get("russia_west_tension", 0.6) + geopolitical.get("middle_east_instability", 0.5)) / 3
        risks["geopolitical"] = {
            "level": "HIGH" if geo_score > 0.5 else "MODERATE" if geo_score > 0.3 else "LOW",
            "score": round(geo_score, 3),
            "drivers": {"us_china": geopolitical.get("us_china_tension", 0.4), "russia_west": geopolitical.get("russia_west_tension", 0.6), "middle_east": geopolitical.get("middle_east_instability", 0.5)},
        }
        scores["geopolitical"] = geo_score

        climate = domain_states.get("climate", {})
        temp_anomaly = climate.get("global_temp_anomaly_c", 1.2)
        climate_score = min(temp_anomaly / 3.0, 1.0)
        risks["climate"] = {
            "level": "CRITICAL" if temp_anomaly > 2.0 else "HIGH" if temp_anomaly > 1.5 else "MODERATE" if temp_anomaly > 1.0 else "LOW",
            "score": round(climate_score, 3),
            "drivers": {"temp_anomaly": temp_anomaly, "co2_ppm": climate.get("co2_ppm", 420), "extreme_weather": climate.get("extreme_weather_index", 0.4)},
        }
        scores["climate"] = climate_score

        economic = domain_states.get("economic", {})
        unemp = economic.get("unemployment_rate", 0.04)
        inflation = economic.get("inflation_rate", 0.03)
        econ_risk = min((unemp * 5 + abs(inflation - 0.02) * 10) / 2, 1.0)
        risks["economic"] = {
            "level": "HIGH" if econ_risk > 0.5 else "MODERATE" if econ_risk > 0.3 else "LOW",
            "score": round(econ_risk, 3),
            "drivers": {"unemployment": round(unemp, 4), "inflation": round(inflation, 4), "interest_rate": economic.get("interest_rate", 0.045), "debt_to_gdp": economic.get("debt_to_gdp", 1.2)},
        }
        scores["economic"] = econ_risk

        demographics = domain_states.get("demographics", {})
        elderly = demographics.get("elderly_pct", 0.10)
        demo_score = min(elderly / 0.3, 1.0)
        risks["demographics"] = {
            "level": "HIGH" if demo_score > 0.6 else "MODERATE" if demo_score > 0.3 else "LOW",
            "score": round(demo_score, 3),
            "drivers": {"elderly_pct": elderly, "fertility": demographics.get("fertility_rate", 2.3), "dependency_ratio": demographics.get("dependency_ratio", 0.54)},
        }
        scores["demographics"] = demo_score

        overall = np.mean(list(scores.values()))
        overall_level = "CRITICAL" if overall > 0.7 else "HIGH" if overall > 0.5 else "MODERATE" if overall > 0.3 else "LOW"

        return {
            "overall_risk": {"level": overall_level, "score": round(float(overall), 3), "domain_scores": {k: round(v, 3) for k, v in scores.items()}},
            "domains": risks,
            "data_sources": domain_states.get("data_sources", {}),
            "timestamp": datetime.now().isoformat(),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/portfolio")
async def portfolio_optimization(
    symbols: str = Query(default="sp500,gold,treasury_10y,bitcoin", description="Comma-separated symbols"),
    n_simulations: int = Query(default=5000, ge=100, le=50000),
    period: str = Query(default="1y", description="Historical period for returns"),
    risk_free_rate: float = Query(default=0.05, ge=0.0, le=0.2, description="Risk-free rate"),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer
        symbol_list = [s.strip() for s in symbols.split(",") if s.strip()]
        multi = data_fetcher.fetch_multi(symbol_list, period=period)

        if len(multi) < 2:
            raise HTTPException(status_code=400, detail="Need at least 2 symbols with data")

        valid_data = {name: arr for name, arr in multi.items() if arr is not None and len(arr) > 10}
        if len(valid_data) < 2:
            raise HTTPException(status_code=400, detail="Insufficient data with >10 observations")

        labels = {
            "sp500": "S&P 500", "nasdaq": "NASDAQ", "vix": "VIX", "gold": "Gold",
            "oil": "Oil", "treasury_10y": "10Y Treasury", "bitcoin": "Bitcoin",
            "usd_index": "USD Index",
        }

        opt = PortfolioOptimizer(n_simulations=n_simulations, risk_free_rate=risk_free_rate, seed=42)
        result = opt.optimize_from_prices(valid_data, n_simulations=n_simulations, risk_free_rate=risk_free_rate)

        optimal_portfolio = {}
        for name, weight in result.optimal_weights.items():
            optimal_portfolio[name] = {
                "weight": weight,
                "label": labels.get(name, name),
                "expected_return": result.individual_returns.get(name, 0),
                "volatility": result.individual_volatilities.get(name, 0),
            }

        conservative_portfolio = {}
        for name, weight in result.conservative_weights.items():
            conservative_portfolio[name] = {
                "weight": weight,
                "label": labels.get(name, name),
            }

        return {
            "optimal_portfolio": optimal_portfolio,
            "conservative_portfolio": conservative_portfolio,
            "optimal_metrics": {
                "expected_return": result.optimal_return,
                "volatility": result.optimal_volatility,
                "sharpe_ratio": result.optimal_sharpe,
                "risk_free_rate": result.risk_free_rate,
            },
            "conservative_metrics": {
                "expected_return": result.conservative_return,
                "volatility": result.conservative_volatility,
            },
            "individual_metrics": {name: {"return": result.individual_returns.get(name, 0), "volatility": result.individual_volatilities.get(name, 0)} for name in result.optimal_weights},
            "efficient_frontier": result.efficient_frontier,
            "n_simulations": result.n_simulations,
            "symbols": list(result.optimal_weights.keys()),
            "timestamp": datetime.now().isoformat(),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/forecast")
async def forecast(
    symbol: str = Query(default="sp500", description="Symbol to forecast: sp500, nasdaq, gold, oil, bitcoin, treasury_10y"),
    days: int = Query(default=90, ge=7, le=730, description="Days to forecast ahead"),
    n_simulations: int = Query(default=1000, ge=100, le=10000, description="Monte Carlo simulations"),
    confidence: str = Query(default="high", description="Confidence: low, medium, high, very_high"),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer
        confidence_map = {
            "low": ConfidenceLevel.LOW, "medium": ConfidenceLevel.MEDIUM,
            "high": ConfidenceLevel.HIGH, "very_high": ConfidenceLevel.VERY_HIGH,
        }
        conf = confidence_map.get(confidence.lower(), ConfidenceLevel.HIGH)

        arr = data_fetcher.get_close_array(symbol, period="2y")
        if arr is None or len(arr) < 30:
            np.random.seed(42)
            arr = np.cumsum(np.random.normal(0.0005, 0.015, 500)) + 100

        current_price = float(arr[-1])
        daily_returns = np.diff(arr) / arr[:-1]
        mu = float(np.mean(daily_returns))
        sigma = float(np.std(daily_returns))

        np.random.seed(42)
        target_date = date.today() + timedelta(days=days)

        n_paths = min(n_simulations, 500)
        paths = np.zeros((n_paths, days))
        for i in range(n_paths):
            path_returns = np.random.normal(mu, sigma, days)
            paths[i] = current_price * np.cumprod(1 + path_returns)

        percentiles = {
            "p10": np.percentile(paths, 10, axis=0).tolist(),
            "p25": np.percentile(paths, 25, axis=0).tolist(),
            "p50": np.percentile(paths, 50, axis=0).tolist(),
            "p75": np.percentile(paths, 75, axis=0).tolist(),
            "p90": np.percentile(paths, 90, axis=0).tolist(),
            "mean": np.mean(paths, axis=0).tolist(),
        }

        final_prices = paths[:, -1]
        opt = PortfolioOptimizer(n_simulations=200, seed=42)
        var95 = opt.var_historical(daily_returns, confidence=0.95)
        cvar95 = opt.cvar_historical(daily_returns, confidence=0.95)
        sortino = opt.sortino_ratio(daily_returns)
        calmar = opt.calmar_ratio(daily_returns)
        mdd = opt.max_drawdown(arr)

        forecast_result = {
            "symbol": symbol,
            "current_price": round(current_price, 2),
            "forecast_days": days,
            "target_date": target_date.isoformat(),
            "mu_daily": round(mu, 6),
            "sigma_daily": round(sigma, 6),
            "mu_annualized": round(mu * 252, 4),
            "sigma_annualized": round(sigma * np.sqrt(252), 4),
            "forecast_price_median": round(float(np.percentile(final_prices, 50)), 2),
            "forecast_price_p10": round(float(np.percentile(final_prices, 10)), 2),
            "forecast_price_p90": round(float(np.percentile(final_prices, 90)), 2),
            "expected_return_annualized": round(mu * 252, 4),
            "max_drawdown_historical": round(float(mdd), 4),
            "percentiles": percentiles,
            "n_simulations": n_simulations,
            "confidence": confidence,
            "data_source": "real" if len(arr) > 100 else "synthetic",
            "risk_metrics": {
                "var_95_daily": round(var95, 6),
                "cvar_95_daily": round(cvar95, 6),
                "sortino_ratio": round(sortino, 4),
                "calmar_ratio": round(calmar, 4),
                "max_drawdown_pct": round(float(mdd) * 100, 2),
            },
        }

        return _serialize(forecast_result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


