        arr = data_fetcher.get_close_array(symbol, period="2y")
        data_source = "real"
        if arr is None or len(arr) < 100:
            np.random.seed(42)
            arr = np.cumsum(np.random.normal(0.0005, 0.015, 300)) + 100
            data_source = "synthetic"

        bt = BacktestEngine(oracle=engine)
        walk_forward = bt.walk_forward(
            arr, window_size=window_size,
            n_windows=n_windows, horizon=horizon,
        )
        model_comparison = bt.compare_models(
            arr, window_size=window_size,
            n_windows=n_windows, horizon=horizon,
        )

