@app.get("/api/market-intelligence")
async def market_intelligence():
    try:
        snapshot = {}
        symbol_map = {"S&P 500": "sp500", "NASDAQ": "nasdaq", "VIX": "vix",
                       "Gold": "gold", "Oil": "oil", "Bitcoin": "bitcoin",
                       "10Y Treasury": "treasury_10y", "USD Index": "usd_index"}

        all_returns = {}
        for label, sym in symbol_map.items():
            arr = data_fetcher.get_close_array(sym, period="2y")
            if arr is not None and len(arr) > 20:
                returns = np.diff(arr) / arr[:-1]
                ann_ret = float(np.mean(returns) * 252 * 100)
                ann_vol = float(np.std(returns, ddof=1) * np.sqrt(252) * 100)
                sharpe = (ann_ret - 5.0) / ann_vol if ann_vol > 0 else 0
                price = float(arr[-1])
                change_1d = float((arr[-1] / arr[-2] - 1) * 100) if len(arr) > 1 else 0
                change_1m = float((arr[-1] / arr[-22] - 1) * 100) if len(arr) > 22 else 0
                change_3m = float((arr[-1] / arr[-63] - 1) * 100) if len(arr) > 63 else 0

                mdd = 0.0
                peak = arr[0]
                for p in arr:
                    if p > peak:
                        peak = p
                    dd = (p - peak) / peak
                    if dd < mdd:
                        mdd = dd

                snapshot[label] = {
                    "symbol": sym,
                    "price": round(price, 2),
                    "change_1d_pct": round(change_1d, 2),
                    "change_1m_pct": round(change_1m, 2),
                    "change_3m_pct": round(change_3m, 2),
                    "ann_return_pct": round(ann_ret, 2),
                    "ann_volatility_pct": round(ann_vol, 2),
                    "sharpe_ratio": round(sharpe, 3),
                    "max_drawdown_pct": round(mdd * 100, 2),
                }
                all_returns[sym] = returns

        signals = []
        for label, data in snapshot.items():
            if data["sharpe_ratio"] > 1.5:
                signals.append({"asset": label, "signal": "strong_buy", "reason": f"Sharpe {data['sharpe_ratio']:.2f}"})
            elif data["sharpe_ratio"] > 0.5:
                signals.append({"asset": label, "signal": "buy", "reason": f"Sharpe {data['sharpe_ratio']:.2f}"})
            elif data["sharpe_ratio"] < -0.5:
                signals.append({"asset": label, "signal": "sell", "reason": f"Sharpe {data['sharpe_ratio']:.2f}"})
            elif data["sharpe_ratio"] < -1.5:
                signals.append({"asset": label, "signal": "strong_sell", "reason": f"Sharpe {data['sharpe_ratio']:.2f}"})
            else:
                signals.append({"asset": label, "signal": "hold", "reason": f"Sharpe {data['sharpe_ratio']:.2f}"})

        vix_data = snapshot.get("VIX", {})
        vix_level = vix_data.get("price", 20)
        if vix_level > 30:
            signals.append({"asset": "Market", "signal": "caution", "reason": f"VIX at {vix_level:.1f} - elevated volatility"})
        elif vix_level < 12:
            signals.append({"asset": "Market", "signal": "complacent", "reason": f"VIX at {vix_level:.1f} - possible complacency"})

        return {
            "snapshot": snapshot,
            "signals": signals,
            "n_assets": len(snapshot),
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


