@app.get("/api/model-comparison-real")
async def model_comparison_real(
    symbol: str = Query(default="sp500", pattern="^(sp500|nasdaq|gold|oil|bitcoin|treasury_10y|vix|usd_index)$"),
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    forecast_days: int = Query(default=30, ge=7, le=365),
):
    try:
        arr = data_fetcher.get_close_array(symbol, period=period)
        if arr is None or len(arr) < 60:
            raise HTTPException(status_code=404, detail=f"Insufficient data for {symbol}")

        returns = np.diff(arr) / arr[:-1]
        current_price = float(arr[-1])

        n_forecast = forecast_days
        mu = float(np.mean(returns))
        sigma = float(np.std(returns, ddof=1))

        stat_forecast = []
        for i in range(n_forecast):
            if i < len(returns):
                stat_forecast.append(current_price * (1 + mu))
            else:
                stat_forecast.append(stat_forecast[-1] * (1 + mu))

        mc_simulations = []
        n_sims = 500
        for _ in range(n_sims):
            path = [current_price]
            sampled = np.random.choice(returns, size=n_forecast, replace=True)
            for r in sampled:
                path.append(path[-1] * (1 + r))
            mc_simulations.append(path)

        mc_final = np.array([s[-1] for s in mc_simulations])
        mc_p10 = float(np.percentile(mc_final, 10))
        mc_p25 = float(np.percentile(mc_final, 25))
        mc_p50 = float(np.percentile(mc_final, 50))
        mc_p75 = float(np.percentile(mc_final, 75))
        mc_p90 = float(np.percentile(mc_final, 90))

        window_size = min(60, len(returns) - 1)
        bayes_prior_mu = float(np.mean(returns[-window_size:])) if len(returns) > window_size else mu
        bayes_prior_sigma = float(np.std(returns[-window_size:], ddof=1)) if len(returns) > window_size else sigma

        simple_forecast = []
        recent_returns = returns[-window_size:] if len(returns) > window_size else returns
        recent_mu = float(np.mean(recent_returns))
        exp_weights = np.exp(np.linspace(0, 1, len(recent_returns)))[-60:] if len(recent_returns) > 60 else np.exp(np.linspace(0, 1, len(recent_returns)))
        ewma_mu = float(np.average(recent_returns, weights=exp_weights[:len(recent_returns)]))
        for i in range(n_forecast):
            simple_forecast.append(current_price * (1 + ewma_mu) ** (i + 1))

        model_results = {
            "statistical": {
                "method": "Mean-Reverting ARIMA-like",
                "p50": round(float(stat_forecast[-1]), 2),
                "direction": "up" if stat_forecast[-1] > current_price else "down",
                "change_pct": round((stat_forecast[-1] / current_price - 1) * 100, 2),
            },
            "monte_carlo": {
                "method": "GBM Monte Carlo (500 sims)",
                "p10": round(mc_p10, 2),
                "p25": round(mc_p25, 2),
                "p50": round(mc_p50, 2),
                "p75": round(mc_p75, 2),
                "p90": round(mc_p90, 2),
                "direction": "up" if mc_p50 > current_price else "down",
                "change_pct": round((mc_p50 / current_price - 1) * 100, 2),
            },
            "bayesian": {
                "method": "Exponentially Weighted Moving Average",
                "p50": round(float(simple_forecast[-1]), 2),
                "direction": "up" if simple_forecast[-1] > current_price else "down",
                "change_pct": round((simple_forecast[-1] / current_price - 1) * 100, 2),
            },
            "ensemble": {
                "method": "Equal-weight average",
                "p50": round((stat_forecast[-1] + mc_p50 + simple_forecast[-1]) / 3, 2),
                "direction": "up" if (stat_forecast[-1] + mc_p50 + simple_forecast[-1]) / 3 > current_price else "down",
                "change_pct": round(((stat_forecast[-1] + mc_p50 + simple_forecast[-1]) / 3 / current_price - 1) * 100, 2),
            },
        }

        consensus_direction = sum(1 for m in model_results.values() if m.get("direction") == "up")
        consensus = "bullish" if consensus_direction >= 3 else "neutral" if consensus_direction == 2 else "bearish"

        return {
            "symbol": symbol,
            "period": period,
            "forecast_days": forecast_days,
            "current_price": round(current_price, 2),
            "models": model_results,
            "consensus": consensus,
            "consensus_score": consensus_direction,
            "n_models": 4,
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/correlation-network")
async def correlation_network(
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    threshold: float = Query(default=0.3, ge=0.0, le=1.0),
):
    try:
        symbols = ["sp500", "nasdaq", "gold", "oil", "bitcoin", "treasury_10y", "usd_index"]
        labels = {"sp500": "S&P 500", "nasdaq": "NASDAQ", "gold": "Gold", "oil": "Oil",
                   "bitcoin": "Bitcoin", "treasury_10y": "10Y Treasury", "usd_index": "USD Index", "vix": "VIX"}
        prices = {}
        for sym in symbols:
            arr = data_fetcher.get_close_array(sym, period=period)
            if arr is not None and len(arr) > 20:
                prices[sym] = arr

        vix_arr = data_fetcher.get_close_array("vix", period=period)
        if vix_arr is not None and len(vix_arr) > 20:
            prices["vix"] = vix_arr

        active_symbols = list(prices.keys())
        min_len = min(len(p) for p in prices.values())
        n = len(active_symbols)

        returns_matrix = np.zeros((min_len - 1, n))
        for i, sym in enumerate(active_symbols):
            arr = prices[sym][-min_len:]
            returns_matrix[:, i] = np.diff(arr) / arr[:-1]

        corr = np.corrcoef(returns_matrix.T)
        mean_returns = np.mean(returns_matrix, axis=0) * 252
        volatilities = np.std(returns_matrix, ddof=1, axis=0) * np.sqrt(252)

        nodes = []
        for i, sym in enumerate(active_symbols):
            node = {
                "id": sym,
                "label": labels.get(sym, sym),
                "return_ann_pct": round(float(mean_returns[i] * 100), 2),
                "volatility_ann_pct": round(float(volatilities[i] * 100), 2),
                "sharpe": round(float((mean_returns[i] - 0.05) / volatilities[i] if volatilities[i] > 0 else 0), 3),
                "group": "positive" if mean_returns[i] > 0 else "negative",
            }
            nodes.append(node)

        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                c = float(corr[i][j])
                if abs(c) >= threshold:
                    edges.append({
                        "source": active_symbols[i],
                        "target": active_symbols[j],
                        "correlation": round(c, 4),
                        "strength": abs(round(c, 4)),
                        "type": "positive" if c > 0 else "negative",
                    })

        avg_corr = float(np.mean(np.abs(corr[np.triu_indices(n, k=1)]))) if n > 1 else 0
        diversification = 1.0 - avg_corr

        clusters = {"risk_on": [], "risk_off": [], "neutral": []}
        for i, sym in enumerate(active_symbols):
            if sym in ["vix", "treasury_10y", "usd_index"]:
                corr_with_sp500 = float(corr[i][active_symbols.index("sp500")]) if "sp500" in active_symbols else 0
                if corr_with_sp500 < -0.2:
                    clusters["risk_off"].append(sym)
                else:
                    clusters["neutral"].append(sym)
            else:
                corr_with_sp500 = float(corr[i][active_symbols.index("sp500")]) if "sp500" in active_symbols else 0
                if corr_with_sp500 > 0.3:
                    clusters["risk_on"].append(sym)
                elif corr_with_sp500 < -0.2:
                    clusters["risk_off"].append(sym)
                else:
                    clusters["neutral"].append(sym)

        return {
            "nodes": nodes,
            "edges": edges,
            "statistics": {
                "avg_absolute_correlation": round(avg_corr, 4),
                "diversification_score": round(diversification, 4),
                "n_assets": n,
                "n_edges": len(edges),
                "period": period,
                "threshold": threshold,
            },
            "clusters": {k: v for k, v in clusters.items() if v},
            "correlation_matrix": {active_symbols[i]: {active_symbols[j]: round(float(corr[i][j]), 4) for j in range(n)} for i in range(n)},
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/rolling-sharpe")
async def rolling_sharpe(
    symbol: str = Query(default="sp500", pattern="^(sp500|nasdaq|gold|oil|bitcoin|treasury_10y|vix|usd_index)$"),
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    window: int = Query(default=21, ge=5, le=252),
    risk_free_rate: float = Query(default=0.05, ge=0.0, le=0.2),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer as PO
        rs_opt = PO(seed=42)
        arr = data_fetcher.get_close_array(symbol, period=period)
        if arr is None or len(arr) < window + 1:
            raise HTTPException(status_code=404, detail=f"Insufficient data for {symbol}")

        returns = np.diff(arr) / arr[:-1]

        rolling_sharpe_data = rs_opt.rolling_sharpe(returns, window=window, risk_free_rate=risk_free_rate / 252)
        downside = rs_opt.downside_risk(returns)
        kelly = rs_opt.kelly_criterion(returns)
        fib = rs_opt.fibonacci_retracement(arr)

        return {
            "symbol": symbol,
            "period": period,
            "window": window,
            "risk_free_rate": risk_free_rate,
            "rolling_sharpe": rolling_sharpe_data,
            "downside_risk": downside,
            "kelly_criterion": kelly,
            "fibonacci": {
                "retracements": {k: round(v, 2) for k, v in fib["retracements"].items()},
                "extensions": {k: round(v, 2) for k, v in fib["extensions"].items()},
                "key_levels": {k: round(v, 2) for k, v in fib["key_levels"].items()},
                "high": round(float(fib["high"]), 2),
                "low": round(float(fib["low"]), 2),
                "current_price": round(float(arr[-1]), 2),
                "trend": fib["trend"],
            },
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/backtest-real-portfolio")
async def backtest_real_portfolio(
    symbols: str = Query(default="sp500,gold,treasury_10y"),
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    weights: str = Query(default="0.5,0.3,0.2"),
    initial_capital: float = Query(default=100000, ge=1000),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer as PO
        bt_opt = PO(n_simulations=200, seed=42)
        symbol_list = [s.strip() for s in symbols.split(",") if s.strip()]
        weight_list = [float(w.strip()) for w in weights.split(",") if w.strip()]
        all_valid = ["sp500", "nasdaq", "gold", "treasury_10y", "oil", "bitcoin", "vix", "usd_index"]
        symbol_list = [s for s in symbol_list if s in all_valid]

        if len(symbol_list) < 2:
            raise HTTPException(status_code=400, detail="Need at least 2 valid symbols")

        if len(weight_list) != len(symbol_list):
            total = sum(weight_list) if weight_list else 1.0
            weight_list = [1.0 / len(symbol_list)] * len(symbol_list)

        weight_arr = np.array(weight_list)
        weight_arr = weight_arr / weight_arr.sum()

        prices_dict = {}
        for sym in symbol_list:
            arr = data_fetcher.get_close_array(sym, period=period)
            if arr is not None and len(arr) > 30:
                prices_dict[sym] = arr

        if len(prices_dict) < 2:
            raise HTTPException(status_code=503, detail="Insufficient market data")

        names = list(prices_dict.keys())
        n = len(names)
        w = np.array(weight_list[:n])
        if len(w) < n:
            w = np.ones(n) / n
        w = w / w.sum()

        min_len = min(len(p) for p in prices_dict.values())
        returns_matrix = np.zeros((min_len - 1, n))
        price_matrix = np.zeros((min_len, n))
        for i, name in enumerate(names):
            arr = prices_dict[name][-min_len:]
            returns_matrix[:, i] = np.diff(arr) / arr[:-1]
            price_matrix[:, i] = arr

        portfolio_returns = returns_matrix @ w
        cumulative = np.cumprod(1 + portfolio_returns)
        portfolio_values = initial_capital * cumulative

        total_return = float((portfolio_values[-1] / initial_capital - 1) * 100)
        ann_return = float(np.mean(portfolio_returns) * 252 * 100)
        ann_vol = float(np.std(portfolio_returns, ddof=1) * np.sqrt(252) * 100)
        sharpe = (ann_return - 5.0) / ann_vol if ann_vol > 0 else 0

        sortino = bt_opt.sortino_ratio(portfolio_returns, risk_free_rate=0.05/252)
        mdd = bt_opt.max_drawdown(portfolio_values)
        calmar = bt_opt.calmar_ratio(portfolio_returns, risk_free_rate=0.05)
        kelly = bt_opt.kelly_criterion(portfolio_returns)
        var_95 = bt_opt.var_historical(portfolio_returns, confidence=0.95)
        cvar_95 = bt_opt.cvar_historical(portfolio_returns, confidence=0.95)

        sample_indices = np.linspace(0, len(portfolio_values) - 1, min(120, len(portfolio_values)), dtype=int)
        equity_curve = [{"day": int(idx), "value": round(float(portfolio_values[idx]), 2)} for idx in sample_indices]

        individual_stats = {}
        for i, name in enumerate(names):
            ind_ret = float(np.mean(returns_matrix[:, i]) * 252 * 100)
            ind_vol = float(np.std(returns_matrix[:, i], ddof=1) * np.sqrt(252) * 100)
            individual_stats[name] = {
                "weight": round(float(w[i]), 4),
                "annualized_return_pct": round(ind_ret, 2),
                "annualized_volatility_pct": round(ind_vol, 2),
                "sharpe_ratio": round((ind_ret - 5.0) / ind_vol, 3) if ind_vol > 0 else 0,
            }

        return {
            "symbols": names,
            "weights": {names[i]: round(float(w[i]), 4) for i in range(n)},
            "initial_capital": initial_capital,
            "final_value": round(float(portfolio_values[-1]), 2),
            "total_return_pct": round(total_return, 2),
            "annualized_return_pct": round(ann_return, 2),
            "annualized_volatility_pct": round(ann_vol, 2),
            "sharpe_ratio": round(sharpe, 3),
            "sortino_ratio": round(sortino, 3),
            "calmar_ratio": round(calmar, 3),
            "max_drawdown_pct": round(float(mdd * 100), 2),
            "var_95_pct": round(float(abs(var_95) * 100), 2),
            "cvar_95_pct": round(float(abs(cvar_95) * 100), 2),
            "kelly_criterion": kelly,
            "data_points": len(portfolio_returns),
            "equity_curve": equity_curve,
            "individual_stats": individual_stats,
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


