@app.get("/api/sortino")
async def sortino_analysis(
    symbol: str = Query(default="sp500", pattern="^(sp500|nasdaq|gold|oil|bitcoin|treasury_10y|vix|usd_index)$"),
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    risk_free_rate: float = Query(default=0.05, ge=0.0, le=0.2),
    target_return: float = Query(default=0.0, ge=-0.5, le=1.0),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer as PO
        s_opt = PO(seed=42)
        arr = data_fetcher.get_close_array(symbol, period=period)
        if arr is None or len(arr) < 30:
            raise HTTPException(status_code=404, detail=f"Insufficient data for {symbol}")

        returns = np.diff(arr) / arr[:-1]

        sortino = s_opt.sortino_ratio(returns, risk_free_rate=risk_free_rate / 252)
        downside = s_opt.downside_risk(returns, target_return=target_return / 252)
        kelly = s_opt.kelly_criterion(returns)
        ann_ret = float(np.mean(returns) * 252 * 100)
        ann_vol = float(np.std(returns, ddof=1) * np.sqrt(252) * 100)

        return {
            "symbol": symbol,
            "period": period,
            "risk_free_rate": risk_free_rate,
            "target_return": target_return,
            "annualized_return_pct": round(ann_ret, 2),
            "annualized_volatility_pct": round(ann_vol, 2),
            "sortino_ratio": round(sortino, 4),
            "downside_risk": downside,
            "kelly_criterion": kelly,
            "data_points": len(returns),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/calmar")
async def calmar_analysis(
    symbol: str = Query(default="sp500", pattern="^(sp500|nasdaq|gold|oil|bitcoin|treasury_10y|vix|usd_index)$"),
    period: str = Query(default="2y", pattern="^(1y|2y|5y|max)$"),
    risk_free_rate: float = Query(default=0.05, ge=0.0, le=0.2),
):
    try:
        from oracle.optimization.portfolio import PortfolioOptimizer as PO
        c_opt = PO(seed=42)
        arr = data_fetcher.get_close_array(symbol, period=period)
        if arr is None or len(arr) < 30:
            raise HTTPException(status_code=404, detail=f"Insufficient data for {symbol}")

        returns = np.diff(arr) / arr[:-1]
        prices = np.cumprod(1 + returns) * 100

        calmar = c_opt.calmar_ratio(returns, risk_free_rate=risk_free_rate)
        mdd = c_opt.max_drawdown(prices)
        sortino = c_opt.sortino_ratio(returns, risk_free_rate=risk_free_rate / 252)

        return {
            "symbol": symbol,
            "period": period,
            "risk_free_rate": risk_free_rate,
            "calmar_ratio": round(calmar, 4),
            "sortino_ratio": round(sortino, 4),
            "max_drawdown_pct": round(float(mdd * 100), 2),
            "annualized_return_pct": round(float(np.mean(returns) * 252 * 100), 2),
            "annualized_volatility_pct": round(float(np.std(returns, ddof=1) * np.sqrt(252) * 100), 2),
            "data_points": len(returns),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


