@app.post("/api/technical-analysis")
async def technical_analysis(request: dict):
    try:
        ta = TechnicalAnalysis()
        symbol = request.get("symbol", "^GSPC")
        period = request.get("period", "1y")
        interval = request.get("interval", "1d")
        indicators = request.get("indicators", ["rsi", "macd", "bollinger", "sma", "ema"])
        fetcher = RealDataFetcher(cache_ttl=3600)
        ticker_map = {"sp500": "^GSPC", "nasdaq": "^IXIC", "vix": "^VIX", "gold": "GC=F", "oil": "CL=F", "bitcoin": "BTC-USD", "treasury": "^TNX", "usd": "DX-Y.NYB"}
        resolved = ticker_map.get(symbol, symbol)
        try:
            data = fetcher.fetch_series(resolved, period=period, interval=interval)
        except Exception:
            data = None
        if data is None or len(data) == 0:
            raise HTTPException(status_code=404, detail=f"No data found for {symbol}")
        close = data["Close"].values if hasattr(data, "Close") else np.array(data)
        result = {"symbol": symbol, "period": period, "interval": interval, "data_points": len(close)}
        if "sma" in indicators:
            result["sma_20"] = {"values": ta.sma(close, 20).tolist(), "period": 20}
            result["sma_50"] = {"values": ta.sma(close, 50).tolist(), "period": 50}
            result["sma_200"] = {"values": ta.sma(close, 200).tolist(), "period": 200}
        if "ema" in indicators:
            result["ema_12"] = {"values": ta.ema(close, 12).tolist(), "period": 12}
            result["ema_26"] = {"values": ta.ema(close, 26).tolist(), "period": 26}
        if "rsi" in indicators:
            rsi_vals = ta.rsi(close, 14)
            result["rsi"] = {
                "values": rsi_vals.tolist() if isinstance(rsi_vals, np.ndarray) else rsi_vals,
                "period": 14,
                "current": round(float(rsi_vals[-1]), 2) if not np.isnan(rsi_vals[-1]) else None,
                "signal": "overbought" if rsi_vals[-1] > 70 else "oversold" if rsi_vals[-1] < 30 else "neutral",
            }
        if "macd" in indicators:
            macd_data = ta.macd(close)
            macd_line = macd_data["macd_line"]
            signal_line = macd_data["signal_line"]
            histogram = macd_data["histogram"]
            result["macd"] = {
                "macd_line_last": round(macd_line[-1], 4) if macd_line else None,
                "signal_line_last": round(signal_line[-1], 4) if signal_line else None,
                "histogram_last": round(histogram[-1], 4) if histogram else None,
                "signal": "bullish" if macd_line[-1] > signal_line[-1] else "bearish",
                "fast_period": 12, "slow_period": 26, "signal_period": 9,
            }
        if "bollinger" in indicators:
            bb = ta.bollinger_bands(close, 20, 2.0)
            upper = bb["upper"]
            lower = bb["lower"]
            result["bollinger"] = {
                "upper_last": round(upper[-1], 2) if upper and not np.isnan(upper[-1]) else None,
                "middle_last": round(bb["middle"][-1], 2) if bb["middle"] and not np.isnan(bb["middle"][-1]) else None,
                "lower_last": round(lower[-1], 2) if lower and not np.isnan(lower[-1]) else None,
                "bandwidth_last": round(bb["bandwidth"][-1], 4) if bb["bandwidth"] and not np.isnan(bb["bandwidth"][-1]) else None,
                "percent_b_last": round(bb["percent_b"][-1], 4) if bb["percent_b"] and not np.isnan(bb["percent_b"][-1]) else None,
                "signal": "above_upper" if close[-1] > upper[-1] else "below_lower" if close[-1] < lower[-1] else "within",
                "period": 20,
            }
        if "stochastic" in indicators:
            if hasattr(data, "High") and hasattr(data, "Low"):
                high = data["High"].values
                low = data["Low"].values
                stoch = ta.stochastic(high, low, close)
                k_last = stoch["k_percent"][-1] if stoch["k_percent"] and not np.isnan(stoch["k_percent"][-1]) else None
                d_last = None
                if isinstance(stoch["d_percent"], list) and len(stoch["d_percent"]) > 0:
                    dv = stoch["d_percent"][-1]
                    if isinstance(dv, float) and not np.isnan(dv):
                        d_last = round(dv, 2)
                result["stochastic"] = {
                    "k_last": round(k_last, 2) if k_last is not None and not np.isnan(k_last) else None,
                    "d_last": d_last,
                    "signal": "overbought" if k_last is not None and k_last > 80 else "oversold" if k_last is not None and k_last < 20 else "neutral",
                }
        if "atr" in indicators:
            if hasattr(data, "High") and hasattr(data, "Low"):
                high = data["High"].values
                low = data["Low"].values
                atr_vals = ta.atr(high, low, close)
                result["atr"] = {
                    "value": round(float(atr_vals[-1]), 4) if isinstance(atr_vals, np.ndarray) and not np.isnan(atr_vals[-1]) else None,
                    "period": 14,
                }
        if "adx" in indicators:
            if hasattr(data, "High") and hasattr(data, "Low"):
                high = data["High"].values
                low = data["Low"].values
                adx_data = ta.adx(high, low, close)
                adx_vals = adx_data["adx"]
                result["adx"] = {
                    "value": round(adx_vals[-1], 2) if adx_vals and not np.isnan(adx_vals[-1]) else None,
                    "plus_di": round(adx_data["plus_di"][-1], 2) if adx_data["plus_di"] and not np.isnan(adx_data["plus_di"][-1]) else None,
                    "minus_di": round(adx_data["minus_di"][-1], 2) if adx_data["minus_di"] and not np.isnan(adx_data["minus_di"][-1]) else None,
                    "signal": "strong_trend" if adx_vals[-1] > 25 else "weak_trend",
                }
        result["last_price"] = round(float(close[-1]), 4)
        return sanitize_nan(result)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


