@app.post("/api/risk/component-var")
async def risk_component_var(request: dict):
    try:
        rd = RiskDecomposition()
        n_assets = int(request.get("n_assets", 3))
        n_periods = int(request.get("n_periods", 252))
        np.random.seed(42)
        returns_matrix = np.random.randn(n_periods, n_assets) * 0.01 + 0.0003
        weights_input = request.get("weights", None)
        if weights_input:
            weights = np.array([float(w) for w in weights_input])
        else:
            weights = np.ones(n_assets) / n_assets
        confidence = float(request.get("confidence", 0.95))
        method = request.get("method", "historical")
        result = rd.component_var(returns_matrix, weights, confidence, method)
        return sanitize_nan(result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


