@app.post("/api/risk/tracking-error")
async def risk_tracking_error(request: dict):
    try:
        rd = RiskDecomposition()
        n_periods = int(request.get("n_periods", 252))
        np.random.seed(42)
        benchmark = np.random.randn(n_periods) * 0.01 + 0.0003
        alpha_val = float(request.get("alpha", 0.001))
        tracking_noise = float(request.get("tracking_noise", 0.002))
        portfolio = benchmark + alpha_val / 252 + np.random.randn(n_periods) * tracking_noise
        result = rd.tracking_error(portfolio, benchmark)
        return sanitize_nan(result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


