@app.post("/api/valuation/ddm")
async def valuation_ddm(request: dict):
    try:
        vm = ValuationModels()
        result = vm.dividend_discount_model(
            float(request.get("current_dividend", 2.0)),
            float(request.get("growth_rate", 0.05)),
            float(request.get("discount_rate", 0.10)),
            terminal_growth=request.get("terminal_growth", None),
            stages=int(request.get("stages", 1)),
            years_per_stage=request.get("years_per_stage", None),
        )
        if request.get("market_price"):
            mp = float(request.get("market_price"))
            result["market_price"] = mp
            result["upside_pct"] = round((result["intrinsic_value"] - mp) / mp * 100, 2) if mp > 0 else 0
            result["signal"] = "undervalued" if result["intrinsic_value"] > mp * 1.1 else "overvalued" if result["intrinsic_value"] < mp * 0.9 else "fair_value"
        return sanitize_nan(result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


