# ===== Energy & Commodities Endpoints =====

class EnergyMixInput(BaseModel):
    oil_price_usd: float = Field(default=75.0, ge=0, le=1000)
    renewable_share_pct: float = Field(default=20.0, ge=0, le=100)
    nuclear_share_pct: float = Field(default=10.0, ge=0, le=100)
    coal_share_pct: float = Field(default=27.0, ge=0, le=100)
    energy_demand_growth: float = Field(default=0.02, ge=-0.1, le=0.5)
    carbon_price_usd: float = Field(default=25.0, ge=0, le=1000)
    grid_stability: float = Field(default=0.7, ge=0, le=1)
    years: int = Field(default=10, ge=1, le=50)
    scenario: str = Field(default="current_policies", pattern="^(current_policies|announced_pledges|net_zero_2050)$")


class EnergySecurityInput(BaseModel):
    oil_price_usd: float = Field(default=75.0, ge=0, le=1000)
    renewable_share_pct: float = Field(default=20.0, ge=0, le=100)
    nuclear_share_pct: float = Field(default=10.0, ge=0, le=100)
    coal_share_pct: float = Field(default=27.0, ge=0, le=100)
    grid_stability: float = Field(default=0.7, ge=0, le=1)
    strategic_reserve_days: float = Field(default=90.0, ge=0, le=730)
    energy_intensity: float = Field(default=5.0, ge=0, le=30)


class CarbonBudgetInput(BaseModel):
    oil_price_usd: float = Field(default=75.0, ge=0, le=1000)
    renewable_share_pct: float = Field(default=20.0, ge=0, le=100)
    carbon_price_usd: float = Field(default=25.0, ge=0, le=1000)
