@app.get("/api/natural-data/auto-populate")
async def natural_auto_populate():
    fetcher = NaturalDataFetcher(cache_ttl=900)
    result = {"status": "ok", "states": {}}
    try:
        usgs = fetcher.fetch_usgs_earthquakes()
        if usgs:
            seismic_dict = fetcher.to_seismic_state(usgs)
            result["states"]["seismic"] = seismic_dict
            result["states"]["seismic_source"] = "usgs"
        else:
            result["states"]["seismic"] = fetcher.to_seismic_state()
            result["states"]["seismic_source"] = "default"
    except Exception:
        result["states"]["seismic"] = fetcher.to_seismic_state()
        result["states"]["seismic_source"] = "error_fallback"
    try:
        noaa_solar = fetcher.fetch_noaa_solar()
        noaa_flare = fetcher.fetch_noaa_flare()
        if noaa_solar or noaa_flare:
            solar_dict = fetcher.to_solar_state(noaa_solar, noaa_flare)
            result["states"]["solar"] = solar_dict
            result["states"]["solar_source"] = "noaa"
        else:
            result["states"]["solar"] = fetcher.to_solar_state()
            result["states"]["solar_source"] = "default"
    except Exception:
        result["states"]["solar"] = fetcher.to_solar_state()
        result["states"]["solar_source"] = "error_fallback"
    try:
        neo_data = fetcher.fetch_nasa_neo()
        if neo_data:
            result["states"]["neo"] = {"neo_count_tracked": neo_data.get("element_count", 0)}
            result["states"]["neo_source"] = "nasa"
        else:
            result["states"]["neo_source"] = "default"
    except Exception:
        result["states"]["neo_source"] = "error_fallback"
    try:
        enso = fetcher.fetch_enso_historical()
        if enso:
            current_nino = enso.get("latest_nino34", 0.5)
            result["states"]["oceanic"] = {"enso_index": current_nino}
            result["states"]["oceanic_source"] = "noaa"
        else:
            result["states"]["oceanic_source"] = "default"
    except Exception:
        result["states"]["oceanic_source"] = "error_fallback"
    return result

