@app.get("/api/yield-curve/real")
async def yield_curve_real():
    try:
        fetcher = RealDataFetcher(cache_ttl=3600)
        treasury_map = {
            "^IRX": {"maturity": 0.25, "label": "13W"},
            "^FVX": {"maturity": 5.0, "label": "5Y"},
            "^TNX": {"maturity": 10.0, "label": "10Y"},
            "^TYX": {"maturity": 30.0, "label": "30Y"},
        }
        observed = []
        for symbol, info in treasury_map.items():
            try:
                data = fetcher.fetch_series(symbol, period="5d", interval="1d")
                if data is not None and len(data) > 0:
                    rate = float(data["Close"].values[-1]) / 100
                    observed.append({"maturity": info["maturity"], "rate": round(rate, 6), "label": info["label"], "symbol": symbol})
            except Exception:
                pass
        if len(observed) < 2:
            raise HTTPException(status_code=404, detail="Insufficient Treasury data")
        maturities = [o["maturity"] for o in observed]
        rates = [o["rate"] for o in observed]
        ycm = YieldCurveModel()
        fit = ycm.fit_nelson_siegel(maturities, rates)
        full_maturities = [0.25, 0.5, 1.0, 2.0, 3.0, 5.0, 7.0, 10.0, 20.0, 30.0]
        if fit.get("success"):
            params = fit["fitted_params"]
            fitted_curve = ycm.nelson_siegel(params["beta0"], params["beta1"], params["beta2"], params["tau"], full_maturities)
        else:
            fitted_curve = None
        fwd = ycm.forward_rates(rates, maturities)
        return sanitize_nan({
            "observed": observed,
            "fitted_curve": fitted_curve,
            "forward_rates": fwd,
            "fit_quality": {"rmse_bps": fit.get("rmse_bps"), "success": fit.get("success", False)},
            "data_date": datetime.now(timezone.utc).strftime("%Y-%m-%d"),
        })
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


