@app.get("/api/prescience")
async def prescience_overview():
    try:
        from oracle.domains.prescience import PrescienceEngine
        pe = PrescienceEngine()
        domain_scores = {}
        try:
            if engine.state.economic_state:
                domain_scores["economic"] = max(0, 1.0 - engine.state.economic_state.debt_to_gdp / 3.0)
            if engine.state.geopolitical_state:
                domain_scores["geopolitical"] = max(0, 1.0 - (engine.state.geopolitical_state.us_china_tension + engine.state.geopolitical_state.russia_west_tension) / 2)
            if engine.state.climate_state:
                domain_scores["climate"] = max(0, 1.0 - engine.state.climate_state.global_temp_anomaly_c / 4.0)
            if engine.state.seismic_state:
                domain_scores["seismic"] = max(0, 1.0 - engine.state.seismic_state.avg_magnitude / 10.0)
            if engine.state.solar_state:
                domain_scores["solar"] = max(0, 1.0 - engine.state.solar_state.flare_probability)
            if engine.state.pandemic_state:
                domain_scores["pandemic"] = max(0, 1.0 - engine.state.pandemic_state.healthcare_capacity / 2.0)
            if engine.state.cyber_state:
                domain_scores["cyber"] = max(0, 1.0 - engine.state.cyber_state.threat_level)
            if engine.state.infrastructure_state:
                domain_scores["infrastructure"] = max(0, 1.0 - engine.state.infrastructure_state.power_grid_reliability)
            if engine.state.supply_chain_state:
                domain_scores["supply_chain"] = max(0, 1.0 - engine.state.supply_chain_state.concentration_risk)
            if engine.state.water_state:
                domain_scores["water"] = max(0, 1.0 - engine.state.water_state.water_stress_index)
            if engine.state.food_state:
                domain_scores["food"] = max(0, 1.0 - engine.state.food_state.supply_chain_disruption / 2.0)
            if engine.state.biodiversity_state:
                domain_scores["biodiversity"] = engine.state.biodiversity_state.genetic_diversity_index
        except Exception:
            pass
        if len(domain_scores) < 3:
            domain_scores = {
                "economic": 0.6, "geopolitical": 0.5, "climate": 0.65,
                "seismic": 0.7, "solar": 0.8, "pandemic": 0.55,
                "cyber": 0.5, "infrastructure": 0.55, "supply_chain": 0.6,
            }
        current_temp = 1.2
        try:
            if engine.state.climate_state:
                current_temp = engine.state.climate_state.global_temp_anomaly_c
        except Exception:
            pass
        return sanitize_nan(pe.predict_prescience(domain_scores, current_temp_anomaly=current_temp))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


