@app.get("/api/signal-monitor")
async def signal_monitor():
    try:
        from oracle.domains.prescience import PrescienceEngine
        pe = PrescienceEngine()
        domain_scores = {}
        try:
            if engine.state.economic_state:
                domain_scores["economic"] = max(0, 1.0 - engine.state.economic_state.debt_to_gdp / 3.0)
            if engine.state.geopolitical_state:
                domain_scores["geopolitical"] = max(0, 1.0 - (engine.state.geopolitical_state.us_china_tension + engine.state.geopolitical_state.russia_west_tension) / 2)
            if engine.state.climate_state:
                domain_scores["climate"] = max(0, 1.0 - engine.state.climate_state.global_temp_anomaly_c / 4.0)
            if engine.state.seismic_state:
                domain_scores["seismic"] = max(0, 1.0 - engine.state.seismic_state.avg_magnitude / 10.0)
            if engine.state.solar_state:
                domain_scores["solar"] = max(0, 1.0 - engine.state.solar_state.flare_probability)
            if engine.state.pandemic_state:
                domain_scores["pandemic"] = max(0, 1.0 - engine.state.pandemic_state.healthcare_capacity / 2.0)
            if engine.state.cyber_state:
                domain_scores["cyber"] = max(0, 1.0 - engine.state.cyber_state.threat_level)
            if engine.state.infrastructure_state:
                domain_scores["infrastructure"] = max(0, 1.0 - engine.state.infrastructure_state.power_grid_reliability)
            if engine.state.supply_chain_state:
                domain_scores["supply_chain"] = max(0, 1.0 - engine.state.supply_chain_state.concentration_risk)
            if engine.state.biodiversity_state:
                domain_scores["biodiversity"] = engine.state.biodiversity_state.genetic_diversity_index
            if engine.state.water_state:
                domain_scores["water"] = max(0, 1.0 - engine.state.water_state.water_stress_index)
            if engine.state.food_state:
                domain_scores["food"] = max(0, 1.0 - engine.state.food_state.supply_chain_disruption / 2.0)
            if engine.state.political_state:
                domain_scores["political"] = engine.state.political_state.government_stability
            if engine.state.space_state:
                domain_scores["space"] = max(0, 1.0 - engine.state.space_state.kessler_syndrome_risk)
            if engine.state.mental_health_state:
                domain_scores["mental_health"] = max(0, 1.0 - engine.state.mental_health_state.depression_prevalence)
            if engine.state.energy_state:
                domain_scores["energy"] = max(0, 1.0 - engine.state.energy_state.get("oil_price", 75) / 200.0)
            if engine.state.sentiment_data:
                domain_scores["sentiment"] = 0.5
        except Exception:
            pass
        if len(domain_scores) < 3:
            domain_scores = {
                "economic": 0.6, "geopolitical": 0.5, "climate": 0.65,
                "seismic": 0.7, "solar": 0.8, "pandemic": 0.55,
                "cyber": 0.5, "infrastructure": 0.55, "supply_chain": 0.6,
            }
        warnings = pe.generate_early_warnings(domain_scores)
        _temp = 1.2
        try:
            if engine.state.climate_state:
                _temp = engine.state.climate_state.global_temp_anomaly_c
        except Exception:
            pass
        tipping = pe.assess_tipping_points(domain_scores, current_temp_anomaly=_temp)
        events = pe.forecast_events(domain_scores, years=10, n_simulations=500)
        prescience = pe.predict_prescience(domain_scores, current_temp_anomaly=_temp)
        active_signals = []
        for w in warnings.get("warnings", []):
            active_signals.append({
                "type": "early_warning",
                "signal_id": w.get("signal_id", ""),
                "category": w.get("category", ""),
                "description": w.get("description", ""),
                "severity": w.get("severity", "elevated"),
                "lead_time_months": w.get("lead_time_months", 12),
                "associated_event": w.get("associated_event", ""),
            })
        for tp in tipping.get("tipping_points", []):
            if tp.get("proximity", 0) > 0.7:
                active_signals.append({
                    "type": "tipping_point",
                    "name": tp.get("name", ""),
                    "proximity": tp.get("proximity", 0),
                    "status": tp.get("status", ""),
                    "irreversibility": tp.get("irreversibility", 0),
                    "impact": tp.get("impact", ""),
                })
        for evt in events.get("events", [])[:5]:
            if evt.get("annual_probability", 0) > 0.03:
                active_signals.append({
                    "type": "high_probability_event",
                    "event_name": evt.get("event_name", ""),
                    "annual_probability": evt.get("annual_probability", 0),
                    "severity": evt.get("severity", 0),
                    "cascade_probability": evt.get("cascade_probability", 0),
                    "affected_domains": evt.get("affected_domains", []),
                })
        return sanitize_nan({
            "domain_scores": domain_scores,
            "prescience_score": prescience.get("prescience_score", 0),
            "alert_level": warnings.get("overall_alert_level", "green"),
            "n_active_signals": len(active_signals),
            "n_early_warnings": warnings.get("n_active_warnings", 0),
            "n_critical_warnings": warnings.get("n_critical", 0),
            "n_tipping_near": tipping.get("near_or_closer", 0),
            "n_events_risk": events.get("n_events_forecast", 0),
            "any_catastrophic_prob": events.get("any_catastrophic_probability", 0),
            "active_signals": active_signals,
            "recommendations": prescience.get("recommendations", []),
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


