@app.post("/api/causal/mediation")
async def causal_mediation(n_samples: int = Query(default=200, ge=50, le=1000)):
    try:
        from oracle.nondeterministic.causal import CausalInference
        import numpy as np
        rng = np.random.RandomState(42)
        n = n_samples
        treatment = rng.binomial(1, 0.5, n)
        mediator = 0.5 * treatment + rng.normal(0, 1, n)
        y = 0.3 * treatment + 0.7 * mediator + rng.normal(0, 0.5, n)
        ci = CausalInference(seed=42)
        result = ci.mediation_analysis(y, treatment, mediator)
        return sanitize_nan(result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/probabilistic/forecast")
async def probabilistic_forecast(mean: float = Query(default=100.0),
                                  std: float = Query(default=10.0, ge=0.01),
                                  distribution: str = Query(default="gaussian"),
                                  observation: Optional[float] = Query(default=None)):
    try:
        from oracle.nondeterministic.probabilistic import ProbabilisticForecaster
        pf = ProbabilisticForecaster()
        if distribution == "student_t":
            result = pf.forecast_t_distribution(mean, std, df=5.0, observation=observation)
        elif distribution == "skew_normal":
            result = pf.forecast_skewnorm(mean, std, skewness=0.5, observation=observation)
        else:
            result = pf.forecast_gaussian(mean, std, observation=observation)
        resp = {
            "point_forecast": result.point_forecast,
            "median": result.median,
            "lower_50": result.lower_50,
            "upper_50": result.upper_50,
            "lower_80": result.lower_80,
            "upper_80": result.upper_80,
            "lower_95": result.lower_95,
            "upper_95": result.upper_95,
            "distribution": result.distribution,
            "skewness": result.skewness,
            "kurtosis": result.kurtosis,
        }
        if result.crps is not None:
            resp["crps"] = result.crps
        if result.pit is not None:
            resp["pit"] = result.pit
        if result.calibration_score is not None:
            resp["calibration_score"] = result.calibration_score
        return sanitize_nan(resp)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


