@app.get("/api/bsts/decompose")
async def bsts_decompose(n_points: int = Query(default=200, ge=50, le=1000),
                          period: int = Query(default=12, ge=2, le=52),
                          n_forecast: int = Query(default=10, ge=1, le=50)):
    try:
        from oracle.prediction.bsts import BayesianStructuralTimeSeries
        import numpy as np
        rng = np.random.RandomState(42)
        t = np.arange(n_points)
        trend = 100 + 0.5 * t
        seasonal = 10 * np.sin(2 * np.pi * t / period)
        noise = rng.normal(0, 2, n_points)
        series = trend + seasonal + noise
        bsts = BayesianStructuralTimeSeries(seed=42)
        result = bsts.decompose(series, period=period, n_forecast=n_forecast)
        return sanitize_nan({
            "trend": result.trend[-50:],
            "seasonal": result.seasonal[-50:],
            "forecast": result.forecast,
            "forecast_lower_95": result.forecast_lower_95,
            "forecast_upper_95": result.forecast_upper_95,
            "r_squared": result.r_squared,
            "state_contributions": result.state_contributions,
            "changepoints": result.changepoints,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/dcc/correlation")
async def dcc_correlation(n_periods: int = Query(default=200, ge=50, le=500)):
    try:
        from oracle.prediction.correlation_dynamics import CorrelationDynamicsModel
        import numpy as np
        rng = np.random.RandomState(42)
        returns = rng.normal(0, 0.02, (n_periods, 3))
        returns[:, 1] = 0.7 * returns[:, 0] + 0.3 * rng.normal(0, 0.02, n_periods)
        returns[:, 2] = -0.3 * returns[:, 0] + 0.7 * rng.normal(0, 0.02, n_periods)
        cdm = CorrelationDynamicsModel(seed=42)
        result = cdm.dcc_garch(returns)
        latest_corr = result.conditional_correlations[-1] if result.conditional_correlations else [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
        return sanitize_nan({
            "conditional_correlation_latest": latest_corr,
            "dcc_alpha": result.dcc_alpha,
            "dcc_beta": result.dcc_beta,
            "persistence": result.persistence,
            "half_life": result.half_life,
            "mean_correlation": result.mean_correlation,
            "correlation_regimes": result.correlation_regimes,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


