@app.post("/api/kan/fit")
async def kan_fit(n_samples: int = Query(default=200, ge=50, le=500),
                  n_features: int = Query(default=3, ge=2, le=10),
                  grid_size: int = Query(default=5, ge=3, le=20),
                  spline_order: int = Query(default=3, ge=1, le=5)):
    try:
        from oracle.prediction.kan import KolmogorovArnoldNetwork
        import numpy as np
        rng = np.random.RandomState(42)
        X = rng.normal(0, 1, (n_samples, n_features))
        y = 2 * X[:, 0] + 0.5 * np.sin(X[:, 1]) + rng.normal(0, 0.3, n_samples)
        kan = KolmogorovArnoldNetwork(grid_size=grid_size, spline_order=spline_order)
        kan.fit(X, y, n_layers=2, max_iter=300, lr=0.01)
        explanation = kan.explain(X)
        return sanitize_nan({
            "prediction": explanation.prediction,
            "feature_importance": explanation.feature_importance,
            "contributions": explanation.contributions,
            "residual": explanation.residual,
            "n_parameters": explanation.n_parameters,
            "layer_info": [{"input_dim": l.input_dim, "output_dim": l.output_dim,
                           "grid_size": l.grid_size, "spline_order": l.spline_order}
                          for l in explanation.layer_info],
            "method": explanation.method,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


