@app.post("/api/dml/estimate")
async def dml_estimate(n_samples: int = Query(default=200, ge=50, le=500),
                       n_features: int = Query(default=3, ge=1, le=10)):
    try:
        from oracle.nondeterministic.causal_advanced import DoubleMachineLearning
        import numpy as np
        rng = np.random.RandomState(42)
        X = rng.normal(0, 1, (n_samples, n_features))
        D = (X[:, 0] > 0).astype(float)
        Y = 2.0 * D + X[:, 0] + rng.normal(0, 0.5, n_samples)
        dml = DoubleMachineLearning(n_cross_fits=2)
        result = dml.fit(Y, D, X)
        return sanitize_nan({
            "treatment_effect": result.treatment_effect,
            "standard_error": result.standard_error,
            "confidence_interval": list(result.confidence_interval),
            "p_value": result.p_value,
            "method": result.method,
            "first_stage_r2": result.first_stage_r2,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


