@app.post("/api/bayesian-opt/acquisition")
async def bayesian_opt_acquisition(n_observations: int = Query(default=20, ge=5, le=100),
                                   method: str = Query(default="ei")):
    try:
        from oracle.prediction.bayesian_optimization import BayesianOptimizer
        import numpy as np
        rng = np.random.RandomState(42)
        X_train = rng.uniform(-3, 3, (n_observations, 1))
        y_train = -X_train[:, 0] ** 2 + rng.normal(0, 0.1, n_observations)
        X_candidates = np.linspace(-3, 3, 50).reshape(-1, 1)
        opt = BayesianOptimizer(seed=42)
        if method == "ucb":
            result = opt.upper_confidence_bound(X_train, y_train, X_candidates)
        elif method == "pi":
            result = opt.probability_of_improvement(X_train, y_train, X_candidates)
        else:
            result = opt.expected_improvement(X_train, y_train, X_candidates)
        return sanitize_nan({
            "x_next": result.x_next,
            "best_acquisition": result.best_acquisition,
            "method": result.method,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/bayesian-opt/optimize")
async def bayesian_opt_optimize(n_iterations: int = Query(default=10, ge=5, le=50)):
    try:
        from oracle.prediction.bayesian_optimization import BayesianOptimizer
        import numpy as np
        def objective(x):
            return -((x[0] - 1.0) ** 2) - 0.5
        opt = BayesianOptimizer(seed=42)
        result = opt.optimize(objective, bounds=[(-5.0, 5.0)], n_iterations=n_iterations)
        return sanitize_nan({
            "best_x": result.best_x,
            "best_value": result.best_value,
            "n_iterations": result.n_iterations,
            "convergence_history": result.convergence_history,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/gp/predict")
async def gp_predict(n_train: int = Query(default=50, ge=10, le=200),
                     n_test: int = Query(default=20, ge=5, le=100),
                     kernel: str = Query(default="rbf")):
    try:
        from oracle.prediction.gaussian_process import GaussianProcessPredictor
        import numpy as np
        rng = np.random.RandomState(42)
        X_train = np.linspace(-5, 5, n_train).reshape(-1, 1)
        y_train = np.sin(X_train[:, 0]) + rng.normal(0, 0.1, n_train)
        X_test = np.linspace(-6, 6, n_test).reshape(-1, 1)
        gp = GaussianProcessPredictor(kernel=kernel, length_scale=2.0)
        gp.fit(X_train, y_train)
        result = gp.predict(X_test)
        return sanitize_nan({
            "mean": result.mean,
            "std": result.std,
            "confidence_lower": result.confidence_lower,
            "confidence_upper": result.confidence_upper,
            "n_training_points": result.n_training_points,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


