@app.post("/api/hmm/detect-regimes")
async def hmm_detect_regimes(n_states: int = Query(default=3, ge=2, le=10),
                             n_samples: int = Query(default=200, ge=50, le=500)):
    try:
        from oracle.prediction.hmm import HiddenMarkovModel
        import numpy as np
        rng = np.random.RandomState(42)
        data = np.concatenate([
            rng.normal(0, 1, n_samples // 3),
            rng.normal(2, 0.5, n_samples // 3),
            rng.normal(-1, 0.8, n_samples - 2 * (n_samples // 3))
        ])
        hmm = HiddenMarkovModel(n_states=n_states, seed=42)
        hmm.fit(data)
        result = hmm.detect_regimes(data)
        return sanitize_nan({
            "regimes": result.regimes[:50],
            "regime_labels": result.regime_labels,
            "regime_statistics": result.regime_statistics,
            "transition_matrix": result.transition_matrix,
            "log_likelihood": result.log_likelihood,
            "n_regimes": result.n_regimes,
            "method": result.method,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


