@app.post("/api/causal-discovery/pc")
async def causal_discovery_pc(n_vars: int = Query(default=4, ge=2, le=10),
                              n_samples: int = Query(default=300, ge=50, le=1000),
                              alpha: float = Query(default=0.05, ge=0.001, le=0.5)):
    try:
        from oracle.nondeterministic.causal_discovery import PCAlgorithm
        import numpy as np
        rng = np.random.RandomState(42)
        data = rng.normal(0, 1, (n_samples, n_vars))
        for i in range(1, n_vars):
            data[:, i] = 0.5 * data[:, i-1] + rng.normal(0, 0.5, n_samples)
        pc = PCAlgorithm(alpha=alpha, max_cond_set=min(n_vars - 2, 3))
        result = pc.fit(data)
        return sanitize_nan({
            "n_edges": result.n_edges,
            "n_directed": result.n_directed,
            "n_undirected": result.n_undirected,
            "independence_tests": result.independence_tests,
            "alpha": result.alpha,
            "bic_score": result.bic_score,
            "edges": [{"from": e.from_node, "to": e.to_node, "type": e.edge_type, "confidence": e.confidence}
                      for e in result.graph.edges[:20]],
            "node_names": result.graph.node_names,
            "method": result.method,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


