async def rl_bandit(n_arms: int = Query(default=5, ge=2, le=20),
                    n_pulls: int = Query(default=300, ge=50, le=1000),
                    method: str = Query(default="ucb1")):
    try:
        from oracle.prediction.reinforcement_learning import MultiArmedBandit
        import numpy as np
        valid_methods = ["ucb1", "thompson", "epsilon_greedy"]
        if method not in valid_methods:
            method = "ucb1"
        bandit = MultiArmedBandit(n_arms=n_arms, method=method, seed=42)
        true_values = [0.1 + 0.15 * i for i in range(n_arms)]
        bandit.fit(n_pulls=n_pulls, true_values=true_values)
        result = bandit.get_result()
        return sanitize_nan({
            "arm_values": result.arm_values,
            "arm_counts": result.arm_counts,
            "optimal_arm": result.optimal_arm,
            "total_reward": result.total_reward,
            "regret": result.regret,
            "n_pulls": result.n_pulls,
            "method": result.method,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


