@app.post("/api/koopman/dmd")
async def koopman_dmd(n_vars: int = Query(default=3, ge=2, le=10),
                     n_time: int = Query(default=50, ge=10, le=200)):
    try:
        from oracle.prediction.koopman import KoopmanOperator
        import numpy as np
        rng = np.random.RandomState(42)
        t = np.linspace(0, 10, n_time)
        X = np.array([np.sin(t + i) for i in range(n_vars)])
        ko = KoopmanOperator(method="dmd")
        ko.fit(X)
        result = ko.forecast(n_ahead=10)
        stability = ko.analyze_stability()
        return sanitize_nan({
            "forecast": result.get("forecast", [])[:10],
            "eigenvalues": [complex(ev).__repr__() for ev in result.get("eigenvalues", [])[:10]],
            "n_modes": result.get("n_modes", 0),
            "n_stable": stability.get("n_stable_modes", 0),
            "n_unstable": stability.get("n_unstable_modes", 0),
            "method": result.get("method", "koopman_dmd"),
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


