        return sanitize_nan({
            "expression": result.best_expression,
            "r_squared": result.best_r_squared,
            "rmse": result.best_rmse,
            "fitness": result.best_fitness,
            "pareto_front": result.pareto_front[:5],
            "complexity": expr_result.complexity,
            "mae": expr_result.mae,
            "method": "symbolic_regression",
        })
