    try:
        tracker = CalibrationTracker()
        for i in range(20):
            pred = 0.02 + i * 0.003
            actual = pred + (i % 5 - 2) * 0.002
            tracker.record(domain="economics", variable="inflation", predicted_value=pred,
                          actual_value=actual, ci_lower=pred - 0.012, ci_upper=pred + 0.012)
            tracker.record(domain="climate", variable="temp_anomaly", predicted_value=1.0 + i * 0.02,
                          actual_value=1.0 + i * 0.02 + (i % 3 - 1) * 0.05, ci_lower=0.8 + i * 0.02, ci_upper=1.2 + i * 0.02)
        curve_data = tracker.calibration_curve(domain=domain)
        return sanitize_nan({
            "bins": curve_data.bin_centers,
            "predicted_probs": curve_data.expected_proportions,
            "actual_frequencies": curve_data.observed_proportions,
            "sample_counts": [curve_data.n_observations] * len(curve_data.bin_centers),
            "calibration_error": curve_data.calibration_error,
            "reliability": curve_data.reliability,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


