@app.post("/api/phase-transition/detect")
async def phase_transition_detect(variable_name: str = Query(default="gdp_growth"),
                                   min_segment_length: int = Query(default=10, ge=5, le=50)):
    try:
        ptd = PhaseTransitionDetector(min_segment_length=min_segment_length)
        np.random.seed(42)
        series = np.concatenate([
            np.random.normal(0.02, 0.005, 50),
            np.random.normal(0.05, 0.008, 50),
            np.random.normal(0.01, 0.006, 50),
        ])
        report = ptd.detect(series, variable_name=variable_name)
        return sanitize_nan({
            "variable": variable_name,
            "n_transitions": len(report.transitions),
            "transitions": [{
                "position": t.transition_date,
                "magnitude": t.transition_strength,
                "direction": "up" if t.after_mean > t.before_mean else "down",
                "confidence": t.confidence,
                "method": t.method,
            } for t in report.transitions],
            "order_parameters": {"order_parameter": report.order_parameter, "n_regimes": report.n_regimes,
                                 "regime_means": report.regime_means, "regime_stds": report.regime_stds,
                                 "regime_boundaries": report.regime_boundaries},
            "summary": f"Detected {len(report.transitions)} phase transitions with {report.n_regimes} regimes (order parameter: {report.order_parameter:.3f})",
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


