async def quantum_uncertainty_map(request: QuantumUncertaintyRequest):
    try:
        preds = {k: (v[0], v[1]) for k, v in request.predictions.items() if len(v) >= 2}
        corrs = None
        if request.correlations:
            corrs = {(k1, k2): v for k1, inner in request.correlations.items() for k2, v in inner.items()}
        result = engine.quantum_uncertainty.map_uncertainty(preds, corrs)
        return sanitize_nan(_dataclass_to_dict(result))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class DecisionTheoryRequest(BaseModel):
    scenarios: Optional[Dict[str, float]] = None
    payoffs: Optional[Dict[str, Dict[str, float]]] = None
    criterion: Optional[str] = "expected_utility"
    risk_attitude: Optional[str] = "risk_averse"


@app.post("/api/decision-theory/decide")
async def decision_theory_decide(request: DecisionTheoryRequest):
    try:
        advisor = DecisionTheoreticAdvisor()
        if request.scenarios:
            advisor.scenarios = request.scenarios
        if request.payoffs:
            advisor.payoffs = request.payoffs
        from oracle.prediction.decision_theory import DecisionCriterion, RiskAttitude
        criterion_map = {c.value: c for c in DecisionCriterion}
        attitude_map = {a.value: a for a in RiskAttitude}
        criterion = criterion_map.get(request.criterion, DecisionCriterion.EXPECTED_UTILITY)
        attitude = attitude_map.get(request.risk_attitude, RiskAttitude.RISK_AVERSE)
        result = advisor.decide(criterion=criterion, attitude=attitude)
        return sanitize_nan(_dataclass_to_dict(result))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


