@app.post("/api/forecast-decompose/decompose")
async def forecast_decompose(request: ForecastDecomposeRequest):
    try:
        from oracle.prediction.forecast_decomposition import DecompositionMethod
        method_map = {m.value: m for m in DecompositionMethod}
        method = method_map.get(request.method, DecompositionMethod.ADDITIVE)
        result = engine.forecast_decomposer.decompose(request.predictions, method=method)
        components = {}
        for var, comps in result.components.items():
            components[var] = [{"name": c.name, "value": c.value, "proportion": c.proportion, "description": c.description} for c in comps]
        return sanitize_nan({
            "method": result.method.value,
            "components": components,
            "trend": result.trend,
            "seasonal": result.seasonal,
            "cyclical": result.cyclical,
            "residual": result.residual,
            "total_explained_variance": result.total_explained_variance,
            "feature_importance": result.feature_importance,
            "regime_contributions": result.regime_contributions,
            "narrative": result.narrative,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/scenario-probability/map")
async def scenario_probability_map(request: ScenarioMapRequest):
    try:
        from oracle.prediction.scenario_probability import ScenarioRelation
        relations = {}
        if request.relations:
            for key, val in request.relations.items():
                parts = key.split(",")
                if len(parts) == 2:
                    relations[(parts[0].strip(), parts[1].strip())] = ScenarioRelation(val)
        result = engine.scenario_probability.map_scenarios(
            request.predictions, request.custom_scenarios, relations if relations else None)
        scenarios = {sid: sanitize_nan(_dataclass_to_dict(s)) for sid, s in result.scenarios.items()}
        paths = [sanitize_nan(_dataclass_to_dict(p)) for p in result.paths]
        return sanitize_nan({
            "scenarios": scenarios,
            "paths": paths,
            "total_probability": result.total_probability,
            "expected_impact": result.expected_impact,
            "top_scenario": result.top_scenario,
            "top_probability": result.top_probability,
            "sensitivity": result.sensitivity,
            "probability_distribution": result.probability_distribution,
            "recommendations": result.recommendations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/causal-enhanced/analyze")
async def causal_enhanced_analyze(request: CausalEnhancedRequest):
    try:
        from oracle.prediction.causal_enhanced import CausalMethod
        ci = engine.causal_enhanced
        t = np.array(request.treatment)
        o = np.array(request.outcome)
        if request.method == "mediation" and request.mediator:
            m = np.array(request.mediator)
            result = ci.mediate(t, o, m)
            return sanitize_nan({
                "total_effect": result.total_effect, "direct_effect": result.direct_effect,
                "indirect_effect": result.indirect_effect, "proportion_mediated": result.proportion_mediated,
                "confidence_interval": list(result.confidence_interval),
            })
        elif request.method == "instrumental" and request.instrument:
            z = np.array(request.instrument)
            result = ci.instrumental_variable(t, o, z)
            return sanitize_nan({
                "iv_estimate": result.iv_estimate, "ols_estimate": result.ols_estimate,
                "first_stage_f": result.first_stage_f, "instrument_relevance": result.instrument_relevance,
                "confidence_interval": list(result.confidence_interval),
            })
        elif request.method == "propensity" and request.covariates:
            cov = np.array(request.covariates)
            result = ci.propensity_score(t, o, cov)
            return sanitize_nan({
                "ate": result.ate, "att": result.att, "atc": result.atc,
                "ps_overlap": result.ps_overlap, "n_matched": result.n_matched,
                "balance_statistics": result.balance_statistics,
                "confidence_interval": list(result.confidence_interval),
            })
        else:
            return {"error": f"Method '{request.method}' requires appropriate data fields"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class PredictiveFateRequest(BaseModel):
    domain_states: Dict[str, float] = {}
    horizon_years: int = 50
    n_simulations: int = 200


class ExistentialRiskRequest(BaseModel):
    domain_states: Dict[str, float] = {}
    custom_risks: Optional[List[Dict]] = None
    discount_rate: Optional[float] = None


class ProphecyRequest(BaseModel):
    predictions: Dict[str, float] = {}
    sensitivities: Optional[Dict[str, Dict[str, float]]] = None
    horizon: str = "medium_term"


@app.post("/api/predictive-fate/project")
async def predictive_fate_project(request: PredictiveFateRequest):
    try:
        from oracle.prediction.predictive_fate import PredictiveFateEngine
        fe = PredictiveFateEngine(n_simulations=request.n_simulations)
        result = fe.project_fate(request.domain_states, horizon_years=request.horizon_years)
        trajectory = [{"year": int(tp.year), "value": round(float(tp.value), 4),
                       "confidence": round(float(tp.confidence), 4)} for tp in result.trajectory]
        divergences = [{"type": d.div_type.value, "year": int(d.year),
                         "strength": round(float(d.strength), 4)} for d in result.divergences]
        attractors = [{"state": {k: round(float(v), 3) for k, v in a.state.items()},
                        "probability": round(float(a.probability), 4),
                        "type": a.attractor_type} for a in result.attractors]
        return sanitize_nan({
            "trajectory": trajectory,
            "collapse_probability": round(float(result.collapse_probability), 4),
            "golden_age_probability": round(float(result.golden_age_probability), 4),
            "stagnation_probability": round(float(result.stagnation_probability), 4),
            "dominant_phase": result.dominant_phase.value,
            "divergences": divergences,
            "attractors": attractors,
            "key_drivers": result.key_drivers,
            "narrative": result.narrative,
            "recommendations": result.recommendations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/existential-risk/assess")
async def existential_risk_assess(request: ExistentialRiskRequest):
    try:
        from oracle.prediction.existential_risk import ExistentialRiskAssessor
        er = ExistentialRiskAssessor()
        if request.discount_rate is not None:
            er.discount_rate = request.discount_rate
        result = er.assess(request.domain_states, custom_risks=request.custom_risks)
        risks = [sanitize_nan({
            "category": r.category.value, "name": r.name,
            "annual_probability": round(float(r.annual_probability), 6),
            "severity": r.severity.value,
            "mitigation_effectiveness": round(float(r.mitigation_effectiveness), 4),
            "trajectory": r.trajectory,
        }) for r in result.risks]
        return sanitize_nan({
            "risks": risks,
            "total_existential_probability": round(float(result.total_existential_probability), 6),
            "risk_timeline": {k: round(float(v), 6) for k, v in result.risk_timeline.items()},
            "mitigation_priorities": result.mitigation_priorities,
            "narrative": result.narrative,
            "recommendations": result.recommendations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/prophecy/synthesize")
async def prophecy_synthesize(request: ProphecyRequest):
    try:
        from oracle.prediction.prophecy import OracleProphecySynthesizer, ProphecyHorizon
        horizon_map = {"immediate": ProphecyHorizon.IMMEDIATE, "short_term": ProphecyHorizon.SHORT,
                         "medium_term": ProphecyHorizon.MEDIUM, "long_term": ProphecyHorizon.LONG,
                         "distant": ProphecyHorizon.DISTANT}
        horizon = horizon_map.get(request.horizon, ProphecyHorizon.MEDIUM)
        os_synth = OracleProphecySynthesizer()
        result = os_synth.prophesize(request.predictions, request.sensitivities, horizon)
        outcomes = [sanitize_nan({
            "variable": o.variable, "prediction": round(float(o.prediction), 4),
            "lower_bound": round(float(o.lower_bound), 4), "upper_bound": round(float(o.upper_bound), 4),
            "confidence": o.confidence.value, "horizon": o.horizon.value,
            "key_drivers": o.key_drivers, "risks": o.risks, "opportunities": o.opportunities,
        }) for o in result.outcomes]
        return sanitize_nan({
            "outcomes": outcomes,
            "overall_confidence": result.overall_confidence.value,
            "overall_trajectory": result.overall_trajectory,
            "critical_junctures": result.critical_junctures,
            "divine_intervention_points": result.divine_intervention_points,
            "narrative": result.narrative,
            "pronouncement": result.pronouncement,
            "recommendations": result.recommendations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class PersonalOracleRequest(BaseModel):
    age: int = 30
    sex: str = "male"
    country: str = "US"
    height_cm: float = 175.0
    weight_kg: float = 75.0
    education_years: int = 16
    annual_income: float = 65000.0
    net_worth: float = 50000.0
    debt: float = 30000.0
    savings_rate: float = 0.10
    exercise_minutes_weekly: int = 90
    sleep_hours: float = 7.0
    diet_quality: float = 0.5
    smoking: str = "never"
    alcohol_drinks_weekly: int = 3
    chronic_conditions: List[str] = []
    family_history: Dict[str, str] = {}
    marital_status: str = "single"
    n_children: int = 0
    close_friends: int = 4
    loneliness: float = 0.3
    purpose_score: float = 0.5
    stress_level: float = 0.4
    relationship_quality: float = 0.6
    job_satisfaction: float = 0.6
    career_growth_rate: float = 0.03
    risk_tolerance: float = 0.5
    resilience: float = 0.6
    use_llm: bool = False


@app.post("/api/personal-oracle/divine")
async def personal_oracle_divine(request: PersonalOracleRequest):
    try:
        from oracle.prediction.personal_oracle import PersonalOracle, PersonInput
        person = PersonInput(
            age=request.age, sex=request.sex, country=request.country,
            height_cm=request.height_cm, weight_kg=request.weight_kg,
            education_years=request.education_years,
            annual_income=request.annual_income, net_worth=request.net_worth,
            debt=request.debt, savings_rate=request.savings_rate,
            exercise_minutes_weekly=request.exercise_minutes_weekly,
            sleep_hours=request.sleep_hours, diet_quality=request.diet_quality,
            smoking=request.smoking, alcohol_drinks_weekly=request.alcohol_drinks_weekly,
            chronic_conditions=request.chronic_conditions,
            family_history=request.family_history,
            marital_status=request.marital_status, n_children=request.n_children,
            close_friends=request.close_friends, loneliness=request.loneliness,
            purpose_score=request.purpose_score, stress_level=request.stress_level,
            relationship_quality=request.relationship_quality,
            job_satisfaction=request.job_satisfaction,
            career_growth_rate=request.career_growth_rate,
            risk_tolerance=request.risk_tolerance, resilience=request.resilience,
        )
        oracle = PersonalOracle(n_simulations=200)
        if request.use_llm:
            result = oracle.divine_with_llm(person)
        else:
            result = oracle.divine(person)
        timeline = [sanitize_nan({
            "year": y.year, "age": y.age,
            "survival_probability": round(float(y.survival_probability), 4),
            "health_score": round(float(y.health_score), 3),
            "income_estimate": round(float(y.income_estimate), 0),
            "net_worth_estimate": round(float(y.net_worth_estimate), 0),
            "life_satisfaction": round(float(y.life_satisfaction), 3),
            "cognitive_score": round(float(y.cognitive_score), 3),
            "events": y.events[:3],
            "phase": y.phase.value,
        }) for y in result.year_by_year]
        inflections = [sanitize_nan({
            "age": ip.age, "description": ip.description,
            "probability": round(float(ip.probability_of_occurring), 3),
            "impact": round(float(ip.impact_magnitude), 2),
            "direction": ip.direction,
            "intervention_windows": ip.intervention_windows,
        }) for ip in result.inflection_points]
        mortality = [sanitize_nan({
            "cause": m.cause, "probability": round(float(m.lifetime_probability), 3),
            "peak_risk_age": m.peak_risk_age, "modifiable_reduction": round(float(m.modifiable_reduction), 3),
        }) for m in result.mortality_breakdown]
        leverage = [sanitize_nan(l) for l in result.highest_leverage_actions]
        return sanitize_nan({
            "life_expectancy": result.life_expectancy,
            "life_expectancy_ci": list(result.life_expectancy_ci),
            "healthspan": result.healthspan,
            "biological_age": result.biological_age,
            "determinism_score": result.determinism_score,
            "agency_score": result.agency_score,
            "timeline": timeline,
            "inflection_points": inflections,
            "mortality_breakdown": mortality,
            "financial_trajectory": result.financial_trajectory_summary,
            "highest_leverage_actions": leverage,
            "monte_carlo": result.monte_carlo_summary,
            "oracle_reading": result.oracle_reading,
            "recommendations": result.recommendations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class DailyOracleRequest(BaseModel):
    use_llm: bool = True
    age: Optional[int] = None
    smoking: Optional[str] = None
    exercise_minutes_weekly: Optional[int] = None
    sleep_hours: Optional[float] = None
    stress_level: Optional[float] = None
    loneliness: Optional[float] = None


@app.post("/api/daily-oracle/divine")
async def daily_oracle_divine(request: DailyOracleRequest):
    try:
        from oracle.prediction.daily_oracle import DailyOracle
        from oracle.prediction.personal_oracle import PersonInput
        oracle = DailyOracle(use_llm=request.use_llm, n_simulations=200)
        person_dict = {}
        if request.age is not None:
            person_dict["age"] = request.age
        if request.smoking is not None:
            person_dict["smoking"] = request.smoking
        if request.exercise_minutes_weekly is not None:
            person_dict["exercise_minutes_weekly"] = request.exercise_minutes_weekly
        if request.sleep_hours is not None:
            person_dict["sleep_hours"] = request.sleep_hours
        if request.stress_level is not None:
            person_dict["stress_level"] = request.stress_level
        if request.loneliness is not None:
            person_dict["loneliness"] = request.loneliness
        result = oracle.divine_today(person_input=person_dict if person_dict else None)
        domain_data = {}
        for d, f in result.domain_forecasts.items():
            domain_data[d] = {
                "current": round(float(f.current_state), 3),
                "forecast_1d": round(float(f.forecast_1d), 3),
                "forecast_1w": round(float(f.forecast_1w), 3),
                "forecast_1m": round(float(f.forecast_1m), 3),
                "confidence": round(float(f.confidence), 3),
                "trend": f.trend.value,
                "regime": f.regime.value,
                "key_drivers": f.key_drivers[:3],
                "risks": f.risks[:2],
                "opportunities": f.opportunities[:2],
            }
        alerts_data = [sanitize_nan({
            "symbol": a.symbol, "domain": a.domain, "level": a.level.value,
            "message": a.message, "evidence": a.evidence[:80], "action": a.action,
        }) for a in result.alerts]
        return sanitize_nan({
            "date": result.date,
            "overall_score": result.overall_score,
            "overall_trend": result.overall_trend.value,
            "regime": result.regime.value,
            "domains": domain_data,
            "alerts": alerts_data,
            "narrative": result.key_narrative,
            "llm_synthesis": result.llm_synthesis,
            "confidence": result.confidence,
            "evidence_count": result.evidence_count,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


