class TSForecastRequest(BaseModel):
    data: List[float] = Field(..., description="Time series data points")
    horizon: int = Field(12, ge=1, le=120, description="Forecast horizon (steps)")
    exogenous: Optional[List[float]] = Field(None, description="Exogenous variable (same length as data)")


@app.post("/api/ts-forecast")
async def ts_forecast(request: TSForecastRequest):
    try:
        from oracle.prediction.ts_forecast import TSForecastEnsemble
        import numpy as np
        ensemble = TSForecastEnsemble(horizon=request.horizon)
        y = np.array(request.data, dtype=float)
        Y_exog = np.array(request.exogenous, dtype=float) if request.exogenous else None
        result = ensemble.forecast(y, Y_exog=Y_exog)
        def mr_to_dict(name, mr):
            return {"method": mr.method.value, "forecast": mr.forecast[:request.horizon],
                    "lower_80": mr.lower_80[:request.horizon], "upper_80": mr.upper_80[:request.horizon],
                    "lower_95": mr.lower_95[:request.horizon], "upper_95": mr.upper_95[:request.horizon],
                    "aic": sanitize_nan(mr.aic), "bic": sanitize_nan(mr.bic),
                    "mse": sanitize_nan(mr.mse), "mae": sanitize_nan(mr.mae), "mape": sanitize_nan(mr.mape),
                    "log_likelihood": sanitize_nan(mr.log_likelihood)}
        return sanitize_nan({
            "forecast": [{"step": fp.step, "value": fp.value, "lower_80": fp.lower_80, "upper_80": fp.upper_80,
                          "lower_95": fp.lower_95, "upper_95": fp.upper_95, "method": fp.method} for fp in result.forecast],
            "method_results": {k: mr_to_dict(k, v) for k, v in result.method_results.items()},
            "ensemble_weights": result.ensemble_weights,
            "backtest": {"window": result.backtest.window, "horizon": result.backtest.horizon,
                         "method_errors": result.backtest.method_errors, "method_weights": result.backtest.method_weights,
                         "avg_error": result.backtest.avg_error} if result.backtest else None,
            "recommendation": result.recommendation, "dominant_regime": result.dominant_regime,
            "trend_direction": result.trend_direction, "anomaly_flags": result.anomaly_flags
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class ScenarioRequest(BaseModel):
    scenario_type: str = Field("retirement", description="Scenario type: retirement, debt_payoff, house_purchase, college_savings, emergency_fund, portfolio_growth, stress_test")
    age: int = Field(30, ge=18, le=100)
    annual_income: float = Field(75000, ge=0)
    monthly_expenses: float = Field(3500, ge=0)
    current_savings: float = Field(50000, ge=0)
    monthly_contribution: float = Field(1000, ge=0)
    debt_balance: float = Field(20000, ge=0)
    debt_interest_rate: float = Field(0.06, ge=0, le=1)
    debt_monthly_payment: float = Field(400, ge=0)
    home_price: float = Field(350000, ge=0)
    down_payment_pct: float = Field(0.20, ge=0, le=1)
    mortgage_rate: float = Field(0.065, ge=0, le=0.2)
    retirement_age: int = Field(65, ge=40, le=100)
    retirement_spending: float = Field(45000, ge=0)
    risk_tolerance: float = Field(0.7, ge=0, le=1)
    stock_allocation: float = Field(0.70, ge=0, le=1)
    bond_allocation: float = Field(0.20, ge=0, le=1)
    college_cost_annual: float = Field(25000, ge=0)
    years_to_college: int = Field(18, ge=0)
    children_count: int = Field(1, ge=0)
    stress_scenario: Optional[str] = Field(None, description="Stress test scenario: 2008_financial_crisis, 2020_covid, 1973_stagflation, 2000_dotcom, 1929_great_depression")


@app.post("/api/scenario/retirement")
async def scenario_retirement(request: ScenarioRequest):
    try:
        from oracle.prediction.scenario_generator import ScenarioGenerator, ScenarioInput
        gen = ScenarioGenerator(seed=42)
        inp = ScenarioInput(age=request.age, annual_income=request.annual_income, monthly_expenses=request.monthly_expenses,
                            current_savings=request.current_savings, monthly_contribution=request.monthly_contribution,
                            debt_balance=request.debt_balance, debt_interest_rate=request.debt_interest_rate,
                            debt_monthly_payment=request.debt_monthly_payment, home_price=request.home_price,
                            down_payment_pct=request.down_payment_pct, mortgage_rate=request.mortgage_rate,
                            retirement_age=request.retirement_age, retirement_spending=request.retirement_spending,
                            risk_tolerance=request.risk_tolerance, stock_allocation=request.stock_allocation,
                            bond_allocation=request.bond_allocation)
        if request.stress_scenario:
            result = gen.stress_test(inp, request.stress_scenario)
        else:
            result = gen.retirement(inp)
        return sanitize_nan({
            "success_probability": result.success_probability, "median_outcome": result.median_outcome,
            "best_case": result.best_case, "worst_case": result.worst_case,
            "p10": result.p10, "p25": result.p25, "p75": result.p75, "p90": result.p90,
            "years_to_goal": result.years_to_goal, "goal_amount": result.goal_amount,
            "key_metrics": result.key_metrics, "recommendations": result.recommendations,
            "narrative": result.narrative,
            "projections": [{"year": p.year, "age": p.age, "portfolio_value": p.portfolio_value,
                             "contribution": p.contribution, "market_return": p.market_return,
                             "inflation": p.inflation, "net_worth": p.net_worth, "phase": p.phase} for p in result.projections[:50]]
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


