class ProphecyNarrationRequest(BaseModel):
    equity: float = Field(0.55, ge=0, le=1)
    volatility: float = Field(0.40, ge=0, le=1)
    commodity: float = Field(0.50, ge=0, le=1)
    crypto: float = Field(0.45, ge=0, le=1)
    bonds: float = Field(0.50, ge=0, le=1)
    currency: float = Field(0.50, ge=0, le=1)
    geopolitical: float = Field(0.40, ge=0, le=1)
    sentiment: float = Field(0.55, ge=0, le=1)
    climate: float = Field(0.55, ge=0, le=1)
    technology: float = Field(0.60, ge=0, le=1)
    economic: float = Field(0.55, ge=0, le=1)
    health: float = Field(0.60, ge=0, le=1)
    inflation: float = Field(0.50, ge=0, le=1)
    labor: float = Field(0.55, ge=0, le=1)
    monetary: float = Field(0.50, ge=0, le=1)
    cascade_triggers: Optional[List[str]] = Field(None, description="Cascade triggers: yield_curve_recession, inflation_shock, tech_disruption, geopolitical_cascade")
    use_llm: bool = Field(False, description="Use LLM for synthesis")


@app.post("/api/prophecy/oracle")
async def prophecy_oracle(request: ProphecyNarrationRequest):
    try:
        from oracle.prediction.prophecy_narrator import ProphecyNarrator
        narrator = ProphecyNarrator(use_llm=request.use_llm, seed=42)
        states = {k: v for k, v in {
            "equity": request.equity, "volatility": request.volatility,
            "commodity": request.commodity, "crypto": request.crypto,
            "bonds": request.bonds, "currency": request.currency,
            "geopolitical": request.geopolitical, "sentiment": request.sentiment,
            "climate": request.climate, "technology": request.technology,
            "economic": request.economic, "health": request.health,
            "inflation": request.inflation, "labor": request.labor,
            "monetary": request.monetary,
        }.items() if v is not None}
        result = narrator.prophesize(states, cascade_triggers=request.cascade_triggers)
        return sanitize_nan({
            "pronouncement": result.pronouncement,
            "overall_trajectory": result.overall_trajectory,
            "overall_confidence": result.overall_confidence.value,
            "multi_horizon": [{"horizon": f.horizon.value, "time_range": f.time_range,
                               "overall_prediction": f.overall_prediction,
                               "confidence": f.confidence.value,
                               "key_events": f.key_events, "risks": f.risks,
                               "opportunities": f.opportunities} for f in result.multi_horizon_forecasts],
            "cascades": [{"chain_name": c.chain_name, "cumulative_probability": c.cumulative_probability,
                          "dominant_risk": c.dominant_risk, "narrative": c.narrative,
                          "steps": [{"event": s.event, "probability": s.probability, "evidence": s.evidence} for s in c.steps]} for c in result.cascade_analyses],
            "counterfactuals": [{"scenario": cf.scenario, "probability_original": cf.probability_original,
                                  "probability_counterfactual": cf.probability_counterfactual,
                                  "probability_delta": cf.probability_delta, "narrative": cf.narrative,
                                  "cascade_effects": cf.cascade_effects, "evidence": cf.evidence} for cf in result.counterfactuals],
            "key_junctures": result.key_junctures,
            "narrative": result.narrative,
            "llm_synthesis": result.llm_synthesis,
            "recommendations": result.recommendations,
            "evidence_citations": result.evidence_citations,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/prediction-tracker/record")
async def prediction_tracker_record(request: Request):
    try:
        body = await request.json()
        from oracle.prediction.prediction_tracker import PredictionTracker
        tracker = PredictionTracker(seed=42)
        pid = tracker.record(
            domain=body.get("domain", "equity"),
            prediction=float(body.get("prediction", 0.5)),
            lower_bound=float(body.get("lower_bound", 0.4)),
            upper_bound=float(body.get("upper_bound", 0.6)),
            horizon_days=int(body.get("horizon_days", 7)),
            confidence=float(body.get("confidence", 0.6)),
            method=body.get("method", "oracle"),
            evidence=body.get("evidence", []),
        )
        return sanitize_nan({"prediction_id": pid, "status": "recorded"})
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/prediction-tracker/resolve")
async def prediction_tracker_resolve(request: Request):
    try:
        body = await request.json()
        tracker = PredictionTracker(seed=42)
        pid = body.get("prediction_id")
        actual = float(body.get("actual_outcome", 0.0))
        resolution_date = body.get("resolution_date")
        entry = tracker.resolve(pid, actual, resolution_date)
        return sanitize_nan({
            "prediction_id": entry.id,
            "status": "resolved",
            "actual_outcome": entry.actual_outcome,
            "prediction": entry.prediction,
            "error": abs(entry.prediction - entry.actual_outcome),
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


