@app.post("/api/causal-event/cascade")
async def causal_event_cascade(request: Request):
    try:
        body = await request.json()
        from oracle.prediction.causal_event import CausalEventFullAnalyzer
        analyzer = CausalEventFullAnalyzer(seed=body.get("seed", 42))
        domain_states = {k: float(v) for k, v in body.get("domain_states", {}).items()}
        result = analyzer.analyze(domain_states=domain_states if domain_states else None)
        cn = result.cascade_network
        return sanitize_nan({
            "chains": [{
                "path": [{"source": cp.source_event, "target": cp.target_event,
                          "boost": cp.probability_boost, "mechanism": cp.mechanism,
                          "type": cp.cascade_type} for cp in ch.chain],
                "total_impact": ch.total_probability_impact,
                "risk_level": ch.risk_level,
                "narrative": ch.narrative,
            } for ch in cn.chains],
            "interaction_edges": [{"source": e.source, "target": e.target,
                                  "strength": e.strength, "mechanism": e.mechanism,
                                  "direction": e.direction} for e in cn.interaction_edges],
            "most_likely_cascade": {
                "path": [{"source": cp.source_event, "target": cp.target_event,
                          "boost": cp.probability_boost, "mechanism": cp.mechanism,
                          "type": cp.cascade_type} for cp in cn.most_likely_cascade.chain],
                "total_impact": cn.most_likely_cascade.total_probability_impact,
                "risk_level": cn.most_likely_cascade.risk_level,
                "narrative": cn.most_likely_cascade.narrative,
            } if cn.most_likely_cascade else None,
            "highest_impact_cascade": {
                "path": [{"source": cp.source_event, "target": cp.target_event,
                          "boost": cp.probability_boost, "mechanism": cp.mechanism,
                          "type": cp.cascade_type} for cp in cn.highest_impact_cascade.chain],
                "total_impact": cn.highest_impact_cascade.total_probability_impact,
                "risk_level": cn.highest_impact_cascade.risk_level,
                "narrative": cn.highest_impact_cascade.narrative,
            } if cn.highest_impact_cascade else None,
            "systemic_risks": cn.systemic_risks,
            "protective_cascades": cn.protective_cascades,
            "overall_cascade_risk": cn.overall_cascade_risk,
        })
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

