@app.post("/api/evolution/inject")
async def evolution_inject(request: Request):
    data = await request.json()
    domain = data.get("domain", "economic")
    context = data.get("context", "")
    try:
        engine = get_engine()
        if not hasattr(engine, 'evolution_engine') or engine.evolution_engine is None:
            from oracle.evolution.continuous_engine import ContinuousEvolutionEngine
            engine.evolution_engine = ContinuousEvolutionEngine()
        result = engine.evolution_engine.mutator.inject_novel_strategy(domain, context)
        if result.success:
            fitness_result = engine.evolution_engine._evaluate_genome(result.genome, domain)
            bd = fitness_result.behavioral_descriptor or BehavioralDescriptor([0.5, 0.5])
            engine.evolution_engine._domain_archives[domain].add_elite(
                genome_id=result.genome.genome_id, bd=bd,
                fitness=fitness_result.fitness,
                generation=engine.evolution_engine.state.generation,
                origin="llm_injection", genome_data=result.genome
            )
            engine.evolution_engine.registry.register(result.genome)
        return {
            "success": result.success, "domain": domain,
            "genome_id": result.genome.genome_id,
            "concept": result.concept,
            "params": {n: f.params for n, f in result.genome.functions.items()}
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

