@app.post("/api/evolution/start")
async def evolution_start(request: Request):
    data = await request.json()
    step_interval = max(1.0, min(float(data.get("step_interval", 60.0)), 3600.0))
    max_duration = data.get("max_duration", None)
    if max_duration is not None:
        max_duration = max(1.0, min(float(max_duration), 3600.0))
    try:
        engine = get_engine()
        if not hasattr(engine, 'evolution_engine') or engine.evolution_engine is None:
            from oracle.evolution.continuous_engine import ContinuousEvolutionEngine
            engine.evolution_engine = ContinuousEvolutionEngine()
        if engine.evolution_engine.is_running:
            return {"status": "already_running", "step_interval": step_interval}
        engine.evolution_engine.start_continuous(
            step_interval=step_interval,
            max_duration=max_duration
        )
        return {"status": "started", "step_interval": step_interval, "max_duration": max_duration}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/evolution/stop")
async def evolution_stop():
    try:
        engine = get_engine()
        if hasattr(engine, 'evolution_engine') and engine.evolution_engine is not None:
            was_running = engine.evolution_engine.is_running
            engine.evolution_engine.stop_continuous()
            if was_running:
                return {"status": "stopped", "generation": engine.evolution_engine.state.generation, "stop_reason": engine.evolution_engine.state.stop_reason}
            return {"status": "was_not_running"}
        return {"status": "no_engine"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

