# ═══════════════════════════════════════════════════════════════════════════════
# Force Whisper — Latent Force Detection & Fate Pressure
# ═══════════════════════════════════════════════════════════════════════════════

class ForceWhisperRequest(BaseModel):
    domains: Dict[str, List[float]] = Field(..., description="Domain name → time series values")
    domain_values: Optional[Dict[str, float]] = Field(None, description="Current scalar values per domain (optional, auto-extracted)")

@app.post("/api/force-whisper/whisper")
async def force_whisper_analysis(req: ForceWhisperRequest):
    """Full Force Whisper analysis — detect latent forces and compute fate pressure level."""
    try:
        engine = get_engine()
        domain_series = {k: np.array(v, dtype=float) for k, v in req.domains.items()}
        report = engine.force_whisper.whisper(domain_series, req.domain_values)
        return sanitize_nan(report.to_dict())
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/force-whisper/detect-forces")
async def force_whisper_detect_forces(req: ForceWhisperRequest):
    """Detect latent force vectors in multi-domain data."""
    try:
        engine = get_engine()
        domain_series = {k: np.array(v, dtype=float) for k, v in req.domains.items()}
        forces = engine.force_whisper.detect_forces(domain_series, req.domain_values)
        return sanitize_nan({"forces": [f.to_dict() for f in forces],
                             "total": len(forces), "active": sum(1 for f in forces if f.is_active)})
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/force-whisper/pressure-gradients")
async def force_whisper_pressure_gradients(req: ForceWhisperRequest):
    """Compute cross-domain pressure gradients."""
    try:
        engine = get_engine()
        domain_series = {k: np.array(v, dtype=float) for k, v in req.domains.items()}
        gradients = engine.force_whisper.detect_pressure_gradients(domain_series)
        return sanitize_nan({"gradients": [g.to_dict() for g in gradients],
                             "n_gradients": len(gradients)})
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/force-whisper/tension-zones")
async def force_whisper_tension_zones(req: ForceWhisperRequest):
    """Identify domains under tension and estimate time to yield."""
    try:
        engine = get_engine()
        domain_series = {k: np.array(v, dtype=float) for k, v in req.domains.items()}
        tension_map = engine.force_whisper._compute_tension(domain_series)
        zones = engine.force_whisper.detect_tension_zones(domain_series, tension_map)
        return sanitize_nan({"tension_zones": [z.to_dict() for z in zones],
                             "n_critical": sum(1 for z in zones if z.is_critical),
                             "tension_map": {k: round(float(v), 4) for k, v in tension_map.items()}})
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

